INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(2523, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(2766, 'plPL', 'Znajdź OOX-22/FE!', 'Odkrywasz dziwne metalowe urządzenie w kształcie jaja. Gdy majstrujesz przy jednym z pokręteł, jajo ożywa i rozkłada się w coś na kształt gnomiej robotycznej maszynerii! Z wnętrza robotycznego jaja dobiega trzeszczący głos.$B$B„Nazywam się Oglethorpe Obnoticus, a mój samonaprowadzający robot się rozbił! Nagrodzę cię za jego odzyskanie. Proszę, zanieś ten sygnalizator do robota!”$B$B„Obliczyłem już dla ciebie współrzędne robota. Jest w jaskini niedaleko Doliny Dzikiej Blizny!”', 'Zanieś sygnalizator alarmowy do samonaprowadzającego robota Oglethorpe\'a w jaskini niedaleko Doliny Dzikiej Blizny.', '', '', '', '', '', '', 0),
(2821, 'plPL', 'Znak jakości', 'Moja filozofia garbarstwa jest prosta: praca musi być najwyższej możliwej jakości – bez kompromisów. Każdy, kto twierdzi, że jakość nie ma znaczenia, próbuje ci wcisnąć działkę nad oceanem w Dun Morogh!$B$BW ostatnich poszukiwaniach najlepszych materiałów natrafiłem na grube skóry yeti. Yeti żyją w Feralas, a wiele z nich można znaleźć w Dolinie Dzikiej Blizny. Chcę kilka takich skór i za dziesięć sztuk dam ci do wyboru jeden z moich skórzanych wyrobów. Jeśli uważasz to za uczciwe, to mamy umowę.', 'Przynieś 10 grubych skór yeti Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2822, 'plPL', 'Znak jakości', 'Jestem dumny ze swoich skórzanych wyrobów i sądzę, że to widać. W jakości nie wolno iść na kompromis. Każdy, kto twierdzi, że jakość nie ma znaczenia, wmówiłby ci też, że ziemia nie skrywa tajemnic!$B$BW ostatnich poszukiwaniach najlepszych materiałów odkryłem grube skóry yeti. Yeti żyją w Feralas, często spotyka się je na zachód stąd, w Dolinie Dzikiej Blizny. Za dziesięć skór dam ci do wyboru jeden z moich skórzanych wyrobów. Jeśli ci to odpowiada, jesteśmy umówieni!', 'Przynieś 10 grubych skór yeti Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(2844, 'plPL', 'Olbrzymi opiekun', 'Do niczego się nie nadaję, $N. Miałem pilnować mojej małej przyjaciółki, Shay, a ona jakoś mi się wymknęła. W sumie nie wiem, co się stało, ale jak ją widziałem ostatni raz, szliśmy przez ruiny tuż na północ stąd.$B$BWszystko było dobrze, a potem się odwróciłem i... już jej nie było.$B$BI teraz nie mogę wymyślić, co mam robić. Masz jakiś pomysł, $N? Strasznie się martwię.$B$BHej, a może ty byś $gposzukał:poszukała; Shay? Twoje nogi chodzą dużo szybciej niż moje.', 'Odnajdź zagubioną nocną elfkę.', '', '', '', '', '', '', 0),
(2845, 'plPL', 'Wędrowna Shay', 'Pomożesz mi wrócić do mojego przyjaciela, Skałogryza? Miał mnie pilnować... ale mam skłonność do oddalania się od czasu do czasu. Jest tyle rzeczy do zobaczenia, że łatwo się rozpraszam.$B$BJest jednak jedna rzecz, która zawsze przyciąga moją uwagę.$B$BW tej skrzyni znajdziesz dzwonek, który jest dla mnie bardzo cenny. Uwielbiam jego dźwięk. Daję ci słowo: jeśli się oddalę, wystarczy, że w niego zadzwonisz, a zaraz przybiegnę z powrotem.', 'Wyjmij ze skrzyni Dzwonek Shay.$B$BOdeskortuj Shay Liściobieżkę do obozu Skałogryza.', 'Zaprowadź Shay Liściobieżkę do obozu Skałogryza', 'Wróć do Skałogryza przy Bliźniaczych Kolosach w Feralas.', '', '', '', '', 0),
(2847, 'plPL', 'Dzika skórzana zbroja', '$n, stajesz się całkiem $gwprawnym garbarzem:wprawną garbarką;! Znam kilka wykrojów, które mogą cię zainteresować... dzika skórzana zbroja! Dzika skóra czerpie z potężnych i chaotycznych właściwości dzikich pnączy, które rosną w miejscach o bujnej roślinności i występują też u niektórych tamtejszych stworzeń. Zbroja wykonana z jej użyciem nie ma sobie równych wśród ludzi o twoich umiejętnościach, gwarantuję.$B$BNauczę cię tego, ale przez jakiś czas będziesz dla mnie pracować. Na początek wystarczy dziesięć sztuk grubej skóry. Potem porozmawiamy o szczegółach.', 'Przynieś 10 sztuk grubej skóry Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2848, 'plPL', 'Dzikie skórzane naramienniki', 'Dzikie skórzane naramienniki świetnie podtrzymują sylwetkę noszącego i zapewniają doskonałą ochronę ramion i barków. Jak każda część dzikiej skórzanej zbroi, przedmiot zyskuje potężną, choć losową premię, gdy wszywa się w niego dzikie pnącze.$B$BZa ten wykrój potrzebuję sześciu grubych zestawów pancernych i dzikiego pnącza. To nie powinno być dla ciebie zbyt wygórowane zamówienie.', 'Przynieś 6 grubych zestawów pancernych i dzikie pnącze Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2849, 'plPL', 'Dzika skórzana kamizelka', 'Dzika skórzana kamizelka to podstawa każdego kompletu dzikiej skórzanej zbroi. Jej konstrukcja łączy się z dzikim pnączem, dając wyrób, który zapewnia maksymalną ochronę tułowia, a jednocześnie pozwala potężnej magii przenikać przez ubiór.$B$BZa ten wykrój potrzebuję dwóch napierśników z żółwich łusek, dwóch par rękawic z żółwich łusek i dzikiego pnącza. To spore zamówienie, ale nie powinno ci sprawić większych trudności.', 'Przynieś 2 napierśniki z żółwich łusek, 2 pary rękawic z żółwich łusek i dzikie pnącze Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2850, 'plPL', 'Dziki skórzany hełm', 'Dziki skórzany hełm zapewnia noszącemu doskonałą ochronę newralgicznych miejsc głowy bez uszczerbku dla wygody. Jak w każdej części dzikiej skórzanej zbroi, wplecione dzikie pnącze daje konstrukcji hełmu potężne, choć losowe wzmocnienie. Noszący skórę na pewno zechcą go mieć!$B$BZa ten wykrój potrzebuję dwóch tunik nocnego pejzażu, dwóch opasek nocnego pejzażu i dzikiego pnącza. Zrealizuj to zamówienie, a wykrój będzie twój!', 'Przynieś 2 tuniki nocnego pejzażu, 2 opaski nocnego pejzażu i dzikie pnącze Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2851, 'plPL', 'Dzikie skórzane buty', 'Sporo się już $gnauczyłeś:nauczyłaś;, $n, ale wciąż masz się czego uczyć. Następne są dzikie skórzane buty, kamień węgielny każdego kompletu.$B$BTe buty wykonuje się tak, by wygodnie otulały stopę i chroniły ją przed niebezpieczeństwami podróży. Miękkie podeszwy to błogosławieństwo dla tych, którzy chcą poruszać się cicho.$B$BZa ten wykrój potrzebuję dwóch par spodni nocnego pejzażu i dwóch par butów nocnego pejzażu. Potrzebuję też dwóch dzikich pnączy... nie jednego. Daj znać, gdy będziesz mieć to wszystko.', 'Przynieś 2 pary spodni nocnego pejzażu, 2 pary butów nocnego pejzażu i 2 dzikie pnącza Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2852, 'plPL', 'Dzikie skórzane nogawice', 'Znasz już podstawy, $n, więc możesz opanować bardziej złożone wyroby. Dzikie skórzane nogawice to jedne z najwytrzymalszych i najpotężniejszych skórzanych elementów ekwipunku. Talia, uda, łydki i narządy wewnętrzne – wszystko to zyskuje ogromną ochronę. W połączeniu ze wzmocnieniem, jakie daje dzikie pnącze, poszukiwacze przygód, którzy je posiądą, będą ci dziękować za każdym razem, gdy cię zobaczą.$B$BZa ten wykrój potrzebuję dwóch hełmów z żółwich łusek, dwóch par karwaszy z żółwich łusek i dwóch dzikich pnączy.', 'Przynieś 2 hełmy z żółwich łusek, 2 pary karwaszy z żółwich łusek i 2 dzikie pnącza Prattowi McGrubbenowi w Warowni Lunopiórej.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2854, 'plPL', 'Dzika skórzana zbroja', '$n, twoja sława garbarza cię wyprzedza. Posiadam wiedzę garbarską, którą warto byłoby ci zdobyć... dzika skórzana zbroja! Dzika skóra czerpie z potężnych i chaotycznych właściwości dzikich pnączy, które rosną w miejscach o bujnej roślinności i występują też u niektórych tamtejszych stworzeń. Zbroja wykonana z jej użyciem nie ma sobie równych wśród rzemieślników o twoich umiejętnościach, gwarantuję.$B$BNauczę cię, ale przez jakiś czas będziesz dla mnie pracować. Na początek wystarczy dziesięć sztuk grubej skóry. Potem porozmawiamy o szczegółach.', 'Przynieś 10 sztuk grubej skóry Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2855, 'plPL', 'Dzikie skórzane naramienniki', 'Dzikie skórzane naramienniki świetnie podtrzymują sylwetkę noszącego i zapewniają doskonałą ochronę ramion i barków. Jak w każdej części dzikiej skórzanej zbroi, gdy wszywa się dzikie pnącze, przedmiot nasyca się losowym, lecz bardzo potężnym wzmocnieniem.$B$BZa ten wykrój potrzebuję sześciu grubych zestawów pancernych i dzikiego pnącza. To nie powinno być dla ciebie zbyt wygórowane zamówienie.', 'Przynieś 6 grubych zestawów pancernych i dzikie pnącze Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2856, 'plPL', 'Dzika skórzana kamizelka', 'Dzika skórzana kamizelka to podstawa każdego kompletu dzikiej skórzanej zbroi. Konstrukcja kamizelki i wplecione w nią dzikie pnącze dają wyrób, który zapewnia maksymalną ochronę tułowia, a jednocześnie pozwala potężnej magii przenikać przez ubiór.$B$BZa ten wykrój potrzebuję dwóch napierśników z żółwich łusek, dwóch par rękawic z żółwich łusek i dzikiego pnącza. To niełatwa lekcja, ale z pewnością masz umiejętności, by jej podołać.', 'Przynieś 2 napierśniki z żółwich łusek, 2 pary rękawic z żółwich łusek i dzikie pnącze Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2857, 'plPL', 'Dziki skórzany hełm', 'Dziki skórzany hełm zapewnia noszącemu doskonałą ochronę newralgicznych miejsc głowy bez uszczerbku dla wygody. Jak w każdej części dzikiej skórzanej zbroi, wplecione dzikie pnącze nasyca konstrukcję hełmu potężną, choć losową magią. Noszący skórę na pewno zechcą go mieć!$B$BZa ten wykrój potrzebuję dwóch tunik nocnego pejzażu, 2 opasek nocnego pejzażu i dzikiego pnącza. Ukończ tę lekcję, a wykrój będzie twój!', 'Przynieś 2 tuniki nocnego pejzażu, 2 opaski nocnego pejzażu i dzikie pnącze Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2858, 'plPL', 'Dzikie skórzane buty', 'Twoja wiedza o dzikiej skórzanej zbroi rośnie, $n, ale wciąż masz się czego uczyć.$B$BDzikie skórzane buty to kamień węgielny każdego kompletu. Wykonuje się je tak, by wygodnie otulały stopę i chroniły ją przed niebezpieczeństwami podróży. Miękkie podeszwy to błogosławieństwo dla tych, którzy chcą poruszać się cicho.$B$BZa ten wykrój potrzebuję dwóch par spodni nocnego pejzażu i dwóch par butów nocnego pejzażu. Potrzebuję też dwóch dzikich pnączy... nie jednego. Gdy będziesz mieć te przedmioty, pójdziemy dalej.', 'Przynieś 2 pary spodni nocnego pejzażu, 2 pary butów nocnego pejzażu i 2 dzikie pnącza Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2859, 'plPL', 'Dzikie skórzane nogawice', 'Możesz już opanować bardziej złożone lekcje, $n. Dzikie skórzane nogawice to jedne z najwytrzymalszych i najpotężniejszych skórzanych elementów ekwipunku. Talia, uda, łydki i narządy wewnętrzne – wszystko to zyskuje ogromną ochronę. W połączeniu ze wzmocnieniem, jakie daje dzikie pnącze, poszukiwacze przygód, którzy je posiądą, będą ci dziękować za każdym razem, gdy cię zobaczą.$B$BAbyś $gzdobył:zdobyła; ten wykrój, potrzebuję dwóch hełmów z żółwich łusek, dwóch par karwaszy z żółwich łusek i dwóch dzikich pnączy.', 'Przynieś 2 hełmy z żółwich łusek, 2 pary karwaszy z żółwich łusek i 2 dzikie pnącza Jangdorowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Jangdora Rączego Kroku w Feralas.', '', '', '', '', 0),
(2862, 'plPL', 'Wojna z Drzewnymi Łapami', 'Gnole... to coś więcej niż utrapienie. To nieustanne zagrożenie dla samego istnienia tego obozu! Nieważne, czy pochodzą z Feralas, czy nie. Jeśli nie wzmocnimy naszej determinacji w walce z nimi, zostaniemy wypędzeni z całego regionu.$B$BOstatnio ataki gnoli na obóz stały się bardziej zażarte. Potrzebujemy twojej pomocy w przetrzebieniu ich szeregów. Przynieś mi dziesięć ich grzyw, a sowicie wynagrodzę twój trud.$B$BIdź!', 'Przynieś 10 grzyw gnoli Drzewnych Łap Hadokenowi Rączemu Krokowi w Obozie Mojache.', '', 'Wróć do Hadokena Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(2863, 'plPL', 'Uderzenie w samców alfa', 'Plan zakłada, że różni przywódcy gnoli – samce alfa, jak sami siebie nazywają – zostaną zabici w szybkim odstępie czasu. Jeśli zdołamy zadać im tak szybki i precyzyjny cios, w ich szeregach zapanuje chaos. Może też wbijemy do ich tępych, zapchlonych łbów, że możemy ich zniszczyć i to zrobimy!$B$BChcę, żebyś $gbył wykonawcą:była wykonawczynią; mojej woli. Wyeliminuj pięciu ich samców alfa w ciągu godziny, $N, inaczej nic z tego nie wyjdzie i utkniemy w martwym punkcie!', 'Zabij 5 samców alfa Drzewnych Łap i w ciągu godziny wróć do Hadokena Rączego Kroku.', '', 'Wróć do Hadokena Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(2866, 'plPL', 'Ruiny Solarsal', 'Na południe od nas leżą Ruiny Solarsal – miejsce znacznie starsze niż obecne czasy. Na początku zbadaliśmy ruiny i nie znaleźliśmy niczego godnego uwagi, więc zostawiliśmy je w spokoju.$B$BBardzo niedawno nagi Nienawistnego Grzebienia zajęły te ruiny w niepokojącej liczbie. Najpierw uznaliśmy to za zapowiedź ataku. Choć to zagrożenie wciąż jest możliwe, sądzimy, że może dziać się coś jeszcze.$B$BUdaj się tam, zbadaj ruiny i szukaj wszystkiego, co zwróci twoją uwagę. Powodzenia, $n.', 'Zbadaj Ruiny Solarsal i sprawdź, co robią tam nagi.', '', '', '', '', '', '', 0),
(2867, 'plPL', 'Powrót do Warowni Lunopiórej', 'Po odkryciu dziwnej altany w sercu Ruin Solarsal nadszedł czas, by wrócić do Warowni Lunopiórej i zdać generał Szandris Lunopiórej relację z tego, co tu odkryto.', 'Wróć do Szandris Lunopiórej w Warowni Lunopiórej i złóż raport ze swoich odkryć.', '', '', '', '', '', '', 0),
(2869, 'plPL', 'Przeciw Nienawistnemu Grzebieniowi', 'W tej chwili najlepiej założyć, że bez względu na to, co knują nagi, w końcu spróbują zająć wyspę dla siebie. Musimy podjąć zdecydowane kroki, by przeciwdziałać temu zagrożeniu, zanim będzie za późno.$B$BPrzynieś mi dziesięć łusek Nienawistnego Grzebienia w dobrym stanie. Chyba oczywiste, jak je zdobyć. Po raz pierwszy zmierzysz się z nagami, a my osłabimy ich obecność na Wyspie Sardor – obie te rzeczy działają na naszą korzyść.', 'Przynieś 10 łusek nag Nienawistnego Grzebienia Latronicusowi Księżycowej Włóczni w Warowni Lunopiórej.', '', 'Wróć do Latronicusa Księżycowej Włóczni w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2870, 'plPL', 'Przeciw lordowi Shalzaru', '$n, nowe raporty zwiadowców dały nam dobre pojęcie o hierarchii dowodzenia nag. W ich szeregach są przedstawiciele arystokracji i to oni o wszystkim decydują.$B$BUstaliliśmy, że jednym z najokrutniejszych arystokratów jest lord Shalzaru. Zwiadowcy donoszą, że podczas niedawnych wykopalisk nag w jaskini na południe od głównych ruin, po drugiej stronie wody, na Wyspie Grozy, osobiście odkrył dziwną relikwię.$B$BPołóż temu kres, kładąc kres jemu, i przynieś mi jego relikwię, żebyśmy mogli ją zbadać.', 'Zabij lorda Shalzaru, a następnie przynieś odkrytą przez niego tajemniczą relikwię Latronicusowi Księżycowej Włóczni w Warowni Lunopiórej.', '', 'Wróć do Latronicusa Księżycowej Włóczni w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2871, 'plPL', 'Dostarczenie relikwii', 'Byłbym wdzięczny, gdybyś $gzechciał:zechciała; zanieść relikwię mojej żonie, Vestii. Jest nie tylko świetną kapłanką naszej społeczności, ale i jedną z najbardziej oczytanych uczonych, jakich można gdziekolwiek spotkać. Ja nie potrafiłbym się połapać w tym urządzeniu, nawet gdyby chodziło o zakład. Ale moja żona... jeśli ktokolwiek może odgadnąć, czym to jest, to właśnie ona... a my musimy to wiedzieć!$B$BJest tuż za zakrętem, bez wątpienia pogrążona w nauce. Dzięki, $n.', 'Dostarcz tajemniczą relikwię Vestii Księżycowej Włóczni w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(2878, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(2879, 'plPL', 'Kostur Equinex', 'To może być Kostur Equinex! Kostur Equinex to w rzeczywistości klucz, którym otwiera się Monolit Equinex w Ruinach Kruczego Wiatru, na stałym lądzie na zachód od Sennego Konaru.$B$BOdnajdź cztery płomienie, które wciąż płoną w tych ruinach: Samhę, Imbela, Byltana i Lahassę. Zdobądź ich esencje, a potem, stojąc przy Monolicie Equinex, użyj esencji, by zasilić kostur. Jeśli to naprawdę Kostur Equinex, zdołasz otworzyć monolit i wydobyć z niego święty artefakt.', 'Zasil Kostur Troyasa i odnajdź Monolit Equinex.', '', 'Wróć do Monolitu Equinex przy Bliźniaczych Kolosach w Feralas.', '', '', '', '', 0),
(2902, 'plPL', 'Śledztwo w sprawie Drzewnych Łap', 'Gnole nie grzeszą rozumem, ale na pewno mają jakąś spisaną strategię swoich ostatnich działań. Gdybyśmy znaleźli te plany, lepiej zrozumielibyśmy, co tak je rozjuszyło.$B$BChcę, żebyś $gwrócił:wróciła; do Drzewnych Łap i $gznalazł:znalazła; cokolwiek, co może przypominać ich plany bitewne. Muszą coś takiego mieć – ich ataki są zbyt dobrze skoordynowane, by obyło się bez planów. Znajdź je i wróć do mnie, gdy je zdobędziesz.', 'Znajdź plany bitewne gnoli gdzieś w obozach gnoli na południe od Obozu Mojache.', '', '', '', '', '', '', 0),
(2903, 'plPL', 'Plany bitewne', 'Plany bitewne gnoli zostały odkryte, pozostaje tylko zanieść je Hadokenowi Rączemu Krokowi w Obozie Mojache. Może on lub ktoś inny w obozie zdoła lepiej zrozumieć, co knują gnole.', 'Zanieś plany bitewne Drzewnych Łap Hadokenowi Rączemu Krokowi w Obozie Mojache.', '', '', '', '', '', '', 0),
(2942, 'plPL', 'Kamień Jutra', 'Gdy tylko wyjmujesz artefakt z monolitu, czujesz, że energia w Kosturze Equinex zaczyna słabnąć.', 'Zanieś błyszczący kamień i Kostur Equinex Troyasowi Księżycowej Bryzie w Warowni Lunopiórej.', '', 'Wróć do Troyasa Księżycowej Bryzy w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2969, 'plPL', 'Wolność dla wszystkich stworzeń', 'Plugawy klan Ponurego Totemu łapie baśniowe smoki, $N. Jer\'kai i ja nie mamy pojęcia, co zamierzają z nimi zrobić, ale najwyraźniej nic dobrego.$B$BNie jesteśmy dość silne, żeby przebić się do obozu i uwolnić schwytane smoki, ale może z twoją pomocą...$B$BJeśli zechcesz i masz silnych przyjaciół, uwolnij stworzenia z klatki tym kluczem i dopilnuj, żeby uszły z życiem. Przez cały czas będę u twojego boku. Jer\'kai zostanie tutaj.', 'Za pomocą klucza do bambusowej klatki uwolnij duszkowce z zagrody w obozie Ponurego Totemu. Przeżyć musi co najmniej 6 duszkowców i Kindal Tkaczka Księżyca.$B$BMasz 6 minut, zanim Kindal uzna, że czas się wycofać, a zadanie zakończy się porażką.', 'Uratuj z niewoli co najmniej 6 duszkowców', 'Wróć do Kindal Tkaczki Księżyca w Feralas.', '', '', '', '', 0),
(2973, 'plPL', 'Blask nowego płaszcza', 'Witaj, $N. Przybyłem z towarzyszami do Feralas z misją od naszych zwierzchników z Orgrimmaru.$B$BMoja towarzyszka życia, Korrin, uwielbia nowe stroje, więc zamierzam uszyć jej nowy płaszcz ozdobiony zwiewnymi skrzydłami baśniowych smoków. Pomożesz mi? Duszkowce o wspaniałych skrzydłach, jakich szukam, żyją na zachód od Obozu Mojache.', 'Przynieś 10 opalizujących skrzydeł duszkowca Kruegowi Czaszkołupowi w Obozie Mojache.', '', 'Wróć do Kruega Czaszkołupa nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(2974, 'plPL', 'Ponure odkrycie', 'Co!? $GNatknąłeś:Natknęłaś; się w okolicy na taurenów? Żartujesz! Jak wyglądali!?$B$BKlan Ponurego Totemu! $GZnalazłeś:Znalazłaś; ich? Belgrom, jeden z naszych zwierzchników, interesuje się tym plemieniem... wyznaczył nawet nagrodę za ich głowy.$B$BMusisz tam wrócić, $N. Wróć i przynieś mi ich rogi... całe stosy, jeśli zdołasz. Z Ponurym Totemem nie ma żartów i nie wolno go lekceważyć. Wróć i zabijaj ich; niech rzeki Feralas spłyną czerwienią od ich mrocznej krwi.', 'Przynieś 20 rogów Ponurego Totemu Kruegowi Czaszkołupowi w Obozie Mojache.', '', 'Wróć do Kruega Czaszkołupa nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(2975, 'plPL', 'Ogry z Feralas', 'Skutków działań plemienia ogrów Gordunni nie sposób w tej okolicy przeoczyć. Rozejrzyj się, $N – sama ich obecność kaleczy tę ziemię. Musimy ich odeprzeć, zanim rozprzestrzenią się jeszcze bardziej po Feralas.$B$BIdź w górę rzeki na północ, a znajdziesz ich posterunek. Przetrzeb ich szeregi, $N. Musimy im pokazać, że nie są tu mile widziani.', 'Rok Orhan z Obozu Mojache chce, żebyś $gzabił:zabiła; 10 ogrów Gordunni, 10 ogrzych magów Gordunni i 5 osiłków Gordunni.', '', 'Wróć do Rok Orhan nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(2978, 'plPL', 'Zwój Gordunni', 'Podnosząc zabrudzony zwój, zauważasz, że zdaje się przedstawiać jakieś spotkanie lub ceremonię. Rok Orhan na pewno zainteresuje się tym zwojem i tym, co może on oznaczać dla Gordunni.', 'Zanieś zwój Gordunni Rok Orhan w Obozie Mojache.', '', '', '', '', '', '', 0),
(2979, 'plPL', 'Mroczna ceremonia', 'Wygląda na to, że to plany jakiejś mrocznej ceremonii, $N. Z tego, co zdołałam odczytać, rytuał ten odprawiają władcy magów Gordunni.$B$BZnajdź jednego z tych władców magów i zdobądź od niego kulę.$B$BKula maga kryje wielką moc i pomoże nam dowiedzieć się więcej o tej ceremonii i o magii, którą władają Gordunni.', 'Rok Orhan z Obozu Mojache chce, żebyś $gznalazł:znalazła; kulę Gordunni.', '', 'Wróć do Rok Orhan nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(2980, 'plPL', 'Ogry z Feralas', 'Skoro $gdowiodłeś:dowiodłaś;, że jesteś $gprawdziwym wojownikiem:prawdziwą wojowniczką;, ufam, że starczy ci odwagi, by kontynuować to zadanie.$B$BUdaj się do Wysokich Ostępów, na południowy zachód stąd. Stoją tam opuszczone i zniszczone budowle, na ziemiach, które niegdyś należały do nocnych elfów. Szukaj tych ruin, a gdy zobaczysz uschnięte drzewa i zbezczeszczoną ziemię, znajdziesz Gordunni. Odeprzyj ich.$B$BTe ogry są znacznie silniejsze od tych, z którymi $gwalczyłeś:walczyłaś; wcześniej, $N. Uważaj.', 'Rok Orhan z Obozu Mojache chce, żebyś $gzabił:zabiła; 10 szamanów Gordunni, 10 czarnoksiężników Gordunni i 5 mocarzy Gordunni.', '', 'Wróć do Rok Orhan nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(2982, 'plPL', 'Wysokie Ostępy', 'Choć to niebezpieczne, Troyas i ja badamy ruiny rozsiane po lasach Feralas.$B$BOstatnio jednak Troyas zaczął sam chodzić do Wysokich Ostępów i naprawdę się o niego martwię. Ogry Gordunni zajęły tamte tereny i nie są przychylne nikomu, kto wkracza na ich terytorium.$B$BMiałam nadzieję, że zechcesz udać się do ruin na południowym wschodzie i wybić część ogrów. Spraw, by było tam trochę bezpieczniej dla mojego Troyasa, a będę ci ogromnie wdzięczna.', 'Angelas Księżycowa Bryza chce, żebyś $gzabił:zabiła; 8 czarnoksiężników Gordunni, 8 szamanów Gordunni i 8 osiłków Gordunni.', '', 'Wróć do Angelas Księżycowej Bryzy w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(2987, 'plPL', 'Kobalt Gordunni', 'Dopiero co przybyłem do Feralas i słyszałem, że ogry Gordunni, które zamieszkują tutejsze dzikie ostępy, mają jakieś ciekawe minerały. Kto wie, co knują, ale strasznie pilnują tego towaru! Nie zostawiają go byle gdzie – o nie, zakopują go, żeby tacy jak ja nie mogli położyć na nim łap.$B$BJeśli zechcesz, dam ci moją łopatę. Idź do Posterunku Gordunni na północ stąd i wykop mi trochę kobaltu Gordunni. Wypatruj niebieskiej poświaty, a potem zacznij kopać!', 'Orwin Gizzmick z Obozu Mojache chce 12 próbek kobaltu Gordunni.', '', 'Wróć do Orwina Gizzmicka nad Jeziorem Dzikiego Wiatru w Feralas.', '', '', '', '', 0),
(3062, 'plPL', 'Mroczne serce', 'Edana Nienawistny Szpon to królowa harpii Północnego Źródła, które mieszkają w ruinach na zachodzie. To czyste zło; słyszałem, że ma serce z kryształu. Nie zna żadnych uczuć poza nienawiścią do wszystkich innych. Musisz stawić czoła Edanie i przynieść mi jej mroczne serce.$B$BSłyszałem o rogu, który noszą przy sobie harpie – zadęcie w niego przy Kamieniach Nienawistnego Szponu, w północnej części ruin, przywoła królową.$B$BWyobraź sobie jej zdziwienie, gdy okaże się, że nie wzywają jej pobratymcy, lecz śmierć.', 'Talo Cierniokopyt z Obozu Mojache chce dostać mroczne serce Edany Nienawistnego Szponu.', '', 'Wróć do Talo Cierniokopyta w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3063, 'plPL', 'Zemsta na Północnym Źródle', 'W swoich czasach byłem doświadczonym łowcą. Nie było w okolicy stworzenia, którego bym się bał. Aż do...$B$BByłem w lesie i ostrzyłem ostrze po ciężkiej walce, gdy wpadłem w zasadzkę. Otoczyły mnie harpie i ledwo zdołałem doczołgać się w bezpieczne miejsce.$B$BNawet teraz wciąż słyszę echo ich wrzasków...$B$BPo tym zdarzeniu nigdy już nie byłem taki sam. Ale nienawiść we mnie kipi – po tylu latach muszę się odegrać.$B$BHarpie Północnego Źródła znajdziesz na zachód stąd. $N, pomścij mnie.', 'Talo Cierniokopyt chce, żebyś $gzabił:zabiła; 4 harpie Północnego Źródła, 4 łotrzyce Północnego Źródła, 4 przywoływaczki wiatru Północnego Źródła i 4 zabójczynie Północnego Źródła.', '', 'Wróć do Talo Cierniokopyta w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3121, 'plPL', 'Dziwna prośba', 'Xerash Płomienne Ostrze, który przebywa w Pawilonie Lariss na północ od Obozu Mojache, ma to, czego potrzebuję, żeby zacząć tu pracę! Przyrządził miksturę, której potrzebuję do mojego... cóż, zobaczysz.$B$BA teraz ruszaj – do Xerasha. Proszę, weź to ze sobą. To skurczona głowa, którą obiecałem Xerashowi w zamian za zioła. Głowa jakiegoś biednego krasnoluda, na którego natknąłem się w lesie. Na pewno będzie zadowolony.', 'Zanieś skurczoną głowę Xerashowi Płomiennemu Ostrzu w Pawilonie Lariss w Feralas.', '', '', '', '', '', '', 0),
(3122, 'plPL', 'Powrót do znachora Uzer\'i', 'Oto zioła, $N. Zanieś je znachorowi Uzer\'i.$B$BPrzekaż mu, proszę, że jestem zadowolony ze skurczonej głowy.', 'Dostarcz sakiewkę na zioła Xerasha znachorowi Uzer\'i w Feralas.', '', '', '', '', '', '', 0),
(3123, 'plPL', 'Próba naczynia', 'To będzie próba – zarówno odprawionego przeze mnie rytuału, jak i twoich umiejętności. Weź to naczynie, $N. Dzięki niemu zyskasz moc, by pomniejszyć stworzenie i uwięzić je w środku.$B$BUdaj się do dziczy na wschód stąd i poszukaj bestii. Twoim celem są groźne żelaznoskóre niedźwiedzie i długozębe biegacze, $N. Zabij je i użyj naczynia na muisek, by je pomniejszyć i schwytać, zanim ich duchy zdołają uciec.', 'Zabij 10 żelaznoskórych niedźwiedzi lub długozębych biegaczy i użyj naczynia na muisek bestii, by pomniejszyć i schwytać zabite bestie.$B$BPrzynieś 10 muisek bestii i naczynie na muisek bestii znachorowi Uzer\'i w Feralas.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3124, 'plPL', 'Muisek hipogryfa', 'Skoro $gdowiodłeś:dowiodłaś;, że jesteś $ggodny:godna; zaufania i potrafisz się posługiwać naczyniem na muisek, chcę teraz, żebyś $gschwytał:schwytała; kolejne stworzenie.$B$BHipogryfy od wielu lat są wiernymi towarzyszami nocnych elfów; ich duchy są lojalne i niezłomne.$B$BTwoim zadaniem jest zabić 10 strzępiastopiórych hipogryfów, a potem szybko pomniejszyć je i schwytać za pomocą naczynia, by zachować ich muisek. Hipogryfy znajdziesz w Wysokich Ostępach, na południe stąd.', 'Zabij 10 strzępiastopiórych hipogryfów dowolnego rodzaju, a następnie użyj naczynia na muisek, by je pomniejszyć i schwytać.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3125, 'plPL', 'Muisek baśniowego smoka', '$N, teraz musisz schwytać stworzenie, które z wyglądu może się wydawać dość kruche, lecz tak naprawdę chodzi nam o jego potężnego ducha. Baśniowe smoki, o których mówię, były sojusznikami nocnych elfów. Musimy któregoś schwytać, by i Horda mogła korzystać z tej siły ducha.$B$BOto naczynie na muisek, $N. Zabij 8 duszkowców lub duszkowych smoków i schwytaj ich muisek. Znajdziesz je na zachód stąd.', 'Zabij 8 duszkowców lub duszkowych smoków. Użyj naczynia na muisek, by pomniejszyć i schwytać zabite baśniowe smoki.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3126, 'plPL', 'Muisek drzewca', 'Naszym kolejnym celem są błądzący leśni wędrowcy, którzy snują się po lesie, $N. Nocne elfy pozyskały drzewce jako sojuszników w walce z Hordą. Może i poruszają się powoli, ale ich roli obrońców nie sposób podważyć.$B$BWkrótce będziemy mogli wykorzystać tę moc dla własnych korzyści.$B$BZnajdź 3 błądzących leśnych wędrowców; zabij ich i użyj naczynia na muisek, by ich pomniejszyć i schwytać.', 'Zabij 3 błądzących leśnych wędrowców. Użyj naczynia na muisek, by pomniejszyć i schwytać zabite drzewce.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3127, 'plPL', 'Muisek górskiego olbrzyma', 'Ostatnie zadanie, jakiego od ciebie wymagam, to udać się na północny zachód i odnaleźć ostatniego wroga.$B$BGórskie olbrzymy opuściły góry, by wesprzeć nocne elfy, gdy na świecie pojawił się Płonący Legion. Poznasz je po ogromnych rozmiarach i po tym, że ziemia zaczyna drżeć, gdy wędrujesz po ich skalistych terenach.$B$BNie mogę się doczekać, by okiełznać moc takich rozmiarów. Zabij 7 górskich olbrzymów, a potem użyj naczynia na muisek, by schwytać ich potężny muisek.', 'Zabij 7 wędrowców lądu lub klifowych olbrzymów. Użyj naczynia na muisek, by pomniejszyć i schwytać zabite górskie olbrzymy.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3128, 'plPL', 'Naturalne materiały', 'Do ukończenia mojego przedsięwzięcia potrzebuję pewnych materiałów... Możesz je zbierać przy okazji innych zadań, które ci dam.$B$BPotrzebuję rozłupanej kłody z drzewca z Feralas. Obrośnięte minerały znajdziesz u górskich olbrzymów i baśniowych smoków na zachodzie. Zdobądź mi też trochę wytrzymałych ścięgien sowostworów z Zaziemia albo hipogryfów z Feralas. Na koniec będę potrzebował dużej ilości metalicznych odłamków z któregokolwiek z tych stworzeń.', 'Przynieś 2 rozłupane kłody, 6 obrośniętych minerałów, 20 wytrzymałych ścięgien i 40 metalicznych odłamków znachorowi Uzer\'i w Obozie Mojache.', '', 'Wróć do znachora Uzer\'i w Obozie Mojache w Feralas.', '', '', '', '', 0),
(3129, 'plPL', 'Broń ducha', 'Nasycanie broni muisek to trudny proces. Teraz, gdy mam wszystkie potrzebne materiały i muisek schwytanych przez ciebie stworzeń, mogę zaczynać. Zaczekaj, proszę; zaraz wrócę.', 'Znachor Uzer\'i chce, żebyś $gzaczekał:zaczekała; chwilę, aż przygotuje broń.', '', '', '', '', '', '', 0),
(3130, 'plPL', 'Przeciw Nienawistnemu Grzebieniowi', 'Na tym etapie skieruję cię do mojego zastępcy, Latronicusa. Od dłuższego czasu uważnie obserwuje siły nag. Ja ocenię ogólną sytuację związaną z nagami. Choć bardzo chciałabym rzucić przeciw nim wszystkie siły, pozostawienie warowni bez obrony przed bezpośrednim atakiem Hordy – albo czegoś gorszego – nie wydaje się najlepszym pomysłem.$B$BTak czy inaczej, Latronicus czeka. Jak dotąd dobra robota, $n. Tak trzymaj.$B$BMożesz odejść.', 'Zamelduj się u Latronicusa Księżycowej Włóczni w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(3363, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(3380, 'plPL', 'Zatopiona Świątynia', 'Na tym świecie są niespokojne duchy, $N. Duchy splugawione przez odosobnienie, związane z pradawnym złem...$B$BSłyszałem o miejscu, które leży głęboko pod powierzchnią ziemi – zostało tam wygnane przez moce większe niż wszystkie, jakie kiedykolwiek widziałem.$B$BJeśli chcesz dowiedzieć się więcej o tym miejscu, Zatopionej Świątyni, odszukaj goblina imieniem Marvon Nitoszukacz. Badał wiele pradawnych miejsc na świecie, a ostatnio słyszano, że opuścił swój dom w Zapadce, by badać ruiny trolli w Tanaris.', 'Odnajdź Marvona Nitoszukacza w Tanaris.', '', '', '', '', '', '', 0),
(3445, 'plPL', 'Zatopiona Świątynia', 'Słyszałam o miejscu, które leży głęboko pod powierzchnią ziemi – zostało tam wygnane przez moce większe niż wszystkie, jakie kiedykolwiek widziałam.$B$BJeśli chcesz dowiedzieć się więcej o tym miejscu, Zatopionej Świątyni, odszukaj goblina imieniem Marvon Nitoszukacz. Podobnie jak Troyas i ja badał wiele pradawnych miejsc na świecie. Ostatnio słyszano, że opuścił swój dom w Zapadce, by badać ruiny trolli w Tanaris.$B$BPowodzenia w poszukiwaniach; od dłuższego czasu nikt nic o nim nie słyszał.', 'Odnajdź Marvona Nitoszukacza w Tanaris.', '', '', '', '', '', '', 0),
(3567, 'plPL', 'Na szczyt', '', '', '', '', '', '', '', '', 0),
(3788, 'plPL', 'Prośba Jonespyre\'a', 'Wybacz, $gprzyjacielu:przyjaciółko;...$B$BMój znajomy chciałby z tobą porozmawiać o badaniach, które prowadzisz we współpracy z Kręgiem Cenariona. To druid o imieniu Quintis Jonespyre i mieszka tu, w Warowni Lunopiórej. Chciałby się z tobą naradzić w sprawie jutroziarna... i bardzo mu zależy, żeby nasza rozmowa nie dotarła do uszu arcydruida.$B$BJeśli cię to interesuje, porozmawiaj z nim; bez wątpienia wtedy wszystko się wyjaśni.', 'Porozmawiaj z Quintisem Jonespyre\'em w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(3791, 'plPL', 'Tajemnica jutroziarna', 'Pozwól, że będę z tobą szczery, $N. Interesuje mnie – nie, niepokoi mnie – dlaczego arcydruid w Darnassus posługuje się imieniem Kręgu Cenariona i jego zasobami, by zdobywać ogromne ilości jutroziarna. Jestem badaczem – klątwy to moja specjalność. Słyszałem, że jutroziarno w odpowiednich warunkach wykazuje właściwości podobne do innych ziół używanych w prymitywnych klątwach.$B$BChcę wiedzieć więcej i proszę cię o pomoc. Przynieś mi dziesięć sztuk jutroziarna, a na pewno się odwdzięczę.', 'Przynieś 10 sztuk jutroziarna Quintisowi Jonespyre\'owi w Warowni Lunopiórej.', '', 'Wróć do Quintisa Jonespyre\'a na Wyspie Sardor w Feralas.', '', '', '', '', 0),
(3792, 'plPL', 'Jutroziarno dla Warowni Lunopiórej', '', '', '', 'Wróć do Quintisa Jonespyre\'a w Feralas.', '', '', '', '', 0),
(3909, 'plPL', 'Eliksir Videre', 'Co to ma znaczyć? Linken... ZAPOMNIAŁ?$B$BAch, rozumiem... Stracił pamięć...$B$BCóż, oto jego miecz. Nie jest jednak ukończony. Znam kogoś, kto może go dokończyć, ale... rozmowa z nim może okazać się trudna.$B$BPosłuchaj, znam kogoś, kto będzie w stanie ci pomóc. Za dużo by teraz tłumaczyć, ale musisz jakoś zdobyć Eliksir Videre. Jedyny, kto może ci w tym pomóc, to Gregan Piwopluj. Trudno go wytropić, ale z tego, co wiem, ostatnio obozował w dziczy Feralas.', 'Odszukaj Gregana Piwopluja w północnym Feralas. Dowiedz się od niego, jak zdobyć Eliksir Videre, a następnie wróć do Donovy Snowden w Zimozdroju.', '', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(4041, 'plPL', 'Eliksir Videre', '', '', '', 'Wróć do Gregana Piwopluja w Feralas.', '', '', '', '', 0),
(4113, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4114, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4116, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4118, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4120, 'plPL', 'Siła skażenia', 'Jako łowca staram się przejmować siłę, którą widzę u swoich przeciwników. Można przechylić szalę walki na swoją korzyść, po prostu dobrze znając wroga, $N.$B$BW miejscu zwanym Spaczoną Knieją, na północ od Jesionowej Kniei, stworzenia zostały skażone substancją zwaną spaczeniem. Niedźwiedzie i wilki oszalały przez nią, ale wierzę, że przy tym stały się jeszcze silniejsze.$B$BIdź, $N. Udaj się do Spaczonej Kniei i zmierz się z tymi bestiami. Przekonaj się na własnej skórze, czy naprawdę są tak silne, jak sądzę.', 'Talo Cierniokopyt z Obozu Mojache w Feralas chce, żebyś $gzabił:zabiła; 12 gniewoszponych grizli i 12 spaczonołapych pustoszycieli w Spaczonej Kniei.', '', 'Wróć do Talo Cierniokopyta w Obozie Mojache w Feralas.', '', '', '', '', 0),
(4124, 'plPL', 'Zaginiony kurier', 'Mój współpracownik, Ginro Rozpalacz Ogniska, szuka pomocy w ustaleniu, gdzie jest kurier i przesyłki, które niósł. Minął mniej więcej tydzień, odkąd kurier zaginął; nasze poszukiwania nie przyniosły rezultatu i utknęliśmy w martwym punkcie. Niestety, musiałem uznać kuriera za zaginionego w akcji.$B$BJeśli masz czas i środki, porozmawiaj, proszę, z Ginro. Powinien być tu, w warowni – może w swojej kwaterze.', 'Porozmawiaj z Ginro Rozpalaczem Ogniska w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(4125, 'plPL', 'Zaginiony kurier', 'Minął mniej więcej tydzień, odkąd kurier Raschal wyruszył do Thalanaar. Dobrze zna Feralas; jest z nami, odkąd generał Lunopióra przyprowadziła tu siły ekspedycyjne. Wiem, że planował popłynąć łodzią wiosłową wzdłuż wybrzeża i spróbować przedostać się przez południowe Feralas, omijając obóz Hordy.$B$BNie zdołałem znaleźć jego łodzi, ale może tobie się uda. Może jest ukryta, a może zatonęła. Tak czy inaczej, może kryć wskazówkę, gdzie on jest. Jeśli coś odkryjesz, daj mi znać.', 'Odnajdź łódź kuriera gdzieś na wybrzeżu Feralas.', '', '', '', '', '', '', 0),
(4127, 'plPL', 'Wrak łodzi', 'Przesuwając dłoń po mule, natrafiasz palcami na rękojeść noża. Wygląda na zadbany i można bezpiecznie założyć, że zgubił go ktoś, kto płynął łodzią. Być może ma to związek z brakującym dużym kawałkiem łodzi.$B$BChwytasz nóż, pamiętając, że Ginro Rozpalacz Ogniska z Warowni Lunopiórej polecił ci wrócić do niego z każdą znalezioną wskazówką. Masz jednak wrażenie, że nie jesteś w wodzie zupełnie $gsam:sama;...', 'Wróć do Warowni Lunopiórej i pokaż Ginro Rozpalaczowi Ogniska znaleziony porzucony nóż.', '', '', '', '', '', '', 0),
(4129, 'plPL', 'Sekret noża', 'Druid naszej warowni, Quintis Jonespyre, ma pewne... nietypowe zdolności. Jedna z nich to psychometria – umiejętność odczytywania historii przedmiotu przez dotyk. Nie pytaj mnie, jak on to robi; zwalam to na magię, której nie rozumiem i nie zamierzam rozumieć. Wiem jednak dwie rzeczy: po pierwsze, widziałem, że to działa, a po drugie, ten nicpoń jest mi coś winien.$B$BZanieś nóż Quintowi do jego domku na drzewie i przekaż mu ode mnie, że jego dług z Kalimdor Hold\'em zostanie spłacony, jeśli odprawi swoje czary nad tym nożem.', 'Zanieś porzucony nóż Quintisowi Jonespyre\'owi w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(4130, 'plPL', 'Odczyt psychometryczny', 'Jeszcze trochę się chwieję, przepraszam. Tak czy inaczej, miałem kilka przydatnych wizji.$B$BRaschal zabiera ze swojej łodzi dwa duże skórzane plecaki i idzie w głąb lądu; potem jednak wraca do łodzi. Widzę skalpy gnoli... natknął się na gnole – chyba nazywają się Drzewne Łapy. Czymś bardzo się martwi – jest niemal przerażony. Tak bardzo, że nie zauważa formujących się za nim żywiołaków wody. Obrazy... urywają się w tym miejscu.$B$BMuszę odpocząć, przepraszam, $N. Powiedz Ginowi, co widziałem. Musi się dowiedzieć.', 'Porozmawiaj z Ginro Rozpalaczem Ogniska w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(4131, 'plPL', 'Gnole Drzewnych Łap', 'Nasi „przyjaciele” z Drzewnych Łap mogli w końcu dopaść Raschala, ale coś mi mówi, że nie tak było. Mimo to od nich najlepiej zacząć poszukiwania.$B$BChciałbym mieć jaśniejszy pomysł, co robić, ale na razie mam tylko: „Przeszukaj obozy Drzewnych Łap – ruszaj”. Wiem, że gnole zatrzymują przedmioty, które znajdą, i walczą o nie między sobą; może natrafiły na plecaki, o których wspomniał Quint. W poprzednich poszukiwaniach nie ryzykowałem otwartej walki, ale skoro Quint miał taką wizję, mówię: rozszarp ich.', 'Przeszukaj obozy gnoli Drzewnych Łap w południowym Feralas w poszukiwaniu rzeczy kuriera lub jego samego.', '', '', '', '', '', '', 0),
(4135, 'plPL', 'Wijąca się Głębia', 'W plecakach są dwa przedmioty: pierwszy to paczka z towarami, która miała trafić do Thalanaar, a drugi to pospiesznie skreślony liścik do nieznanego adresata.$B$BLiścik opowiada o odkryciu podstępnych, podobnych do owadów stworzeń na południe od obozów gnoli, w miejscu zwanym Wijącą się Głębią. Autor czuł potrzebę, by zbadać to osobiście, jakby stanowiło to poważne zagrożenie dla całego Feralas. Liścik jest podpisany: „Raschal z Warowni Lunopiórej”.$B$BWygląda na to, że $gustaliłeś:ustaliłaś;, dokąd ostatecznie udał się Raschal.', 'Skoro odkryto miejsce, w którym ostatnio przebywał Raschal, kontynuuj poszukiwania jego lub jego szczątków w Wijącej się Głębi. Według liściku znajduje się ona na południe od obozów gnoli Drzewnych Łap.', '', '', '', '', '', '', 0),
(4141, 'plPL', 'Muigin i Larion', 'Widzisz tam Lariona? To przez NIEGO tu jesteśmy!$B$BMówiłem mu, że idziemy w złą stronę, ale czy słuchał? I wyobraź sobie, że to on nie chce się do mnie odzywać! Cóż, dopóki nie zmieni zdania, zabawmy się trochę jego kosztem.$B$B$GZauważyłeś:Zauważyłaś; te dziwne, podobne do roślin stwory w okolicy? Same z nimi kłopoty, naprawdę, ale myślę, że odpowiednio wytresowane słuchałyby moich poleceń.$B$BNajpierw jednak potrzebuję kilku próbek do zbadania. Dasz radę jakieś zebrać?', 'Zbierz 15 krwawych płatków i wróć do Muigina.', '', 'Wróć do Muigina w Kraterze Un\'Goro.', '', '', '', '', 0),
(4142, 'plPL', 'Wizyta u Gregana', 'Nie bardzo wiem, co o tym myśleć, $N. Te rośliny... wydają się mieć odrobinę inteligencji.$B$BAle nie jestem ekspertem. Znam za to kogoś, kto nim jest!$B$BUdaj się do północnego Feralas i poszukaj mojego kumpla, Gregana Piwopluja. Zna się na takich sprawach.$B$BJestem pewien, że Gregan nam pomoże. Znajdziesz go gdzieś w dziczy; to nie ten typ, co mieszka w wielkim mieście.', 'Zanieś krwawopłatek Greganowi Piwoplujowi w Feralas.', '', '', '', '', '', '', 0),
(4143, 'plPL', 'Mgiełka zła', 'Prawdę mówiąc, $N, nigdy w swoich podróżach nie widziałem takich roślin. Może powinienem wybrać się do tego krateru...$B$BTak czy inaczej, chyba wiem, czego szuka Muigin – mgiełki Atal\'ai. Paskudztwo, trudno je zebrać, ale to dokładnie to, czego mu trzeba, żeby zapanować nad tymi małymi potworkami.$B$BMusisz udać się do Świątyni Atal\'Hakkar na Moczarach Smutków. Mgiełkę Atal\'ai można zebrać z głębinowych czyhaczy, mułowych robaków i szlamów, które tam żyją. Powodzenia, $N!', 'Zbierz 5 próbek mgiełki Atal\'ai, a następnie wróć do Muigina w Kraterze Un\'Goro.', '', 'Wróć do Muigina w Kraterze Un\'Goro.', '', '', '', '', 0),
(4144, 'plPL', 'Kiełki krwawopłatka', '', '', '', 'Wróć do Muigina w Kraterze Un\'Goro.', '', '', '', '', 0),
(4265, 'plPL', 'Uwolniony z roju', 'Gdy dotykasz kapsuły, ta nieco się rozchyla, odsłaniając nocnego elfa, który ku twojemu zaskoczeniu wciąż żyje. Wydaje się w dobrym zdrowiu, choć jest mocno oszołomiony. Gdy pomagasz mu wydostać się z kapsuły, odzyskuje przytomność.$B$B„Dzięki niech będą Elunie – $guratowałeś:uratowałaś; mnie, $gprzyjacielu:przyjaciółko;! Jestem... jestem Raschal. Obudziłem się sparaliżowany w tej kapsule, gdy te robale mnie obezwładniły. Czy przysłała cię warownia?”$B$BWygląda na to, że $godnalazłeś:odnalazłaś; zaginionego kuriera!', 'Uwolnij Raschala z roju Zukk\'ash.$B$BWróć do Ginro Rozpalacza Ogniska w Warowni Lunopiórej i powiedz mu, że Raschal żyje i ma się dobrze.', 'Uwolnij Raschala.', 'Wróć do Ginro Rozpalacza Ogniska w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(4266, 'plPL', 'Powitanie bohatera', '$N, generał Szandris Lunopióra chce z tobą osobiście porozmawiać. Bez wątpienia pragnie ci podziękować za służbę dla warowni, ale wiem też, że chce porozmawiać o owadzich stworzeniach, z którymi ty i Raschal zmierzyliście się w południowym Feralas. Raporty o tych owadach Zukk\'ash są... przerażające, delikatnie mówiąc.$B$BGenerał Lunopióra czeka na ciebie w głównej części warowni.', 'Porozmawiaj z Szandris Lunopiórą w Warowni Lunopiórej.', '', '', '', '', '', '', 0),
(4281, 'plPL', 'Dostawa do Thalanaar', 'Ta paczka z towarami, którą $gznalazłeś:znalazłaś; w obozach gnoli Drzewnych Łap, miała zostać dostarczona do małej stacji przydrożnej Thalanaar w południowo-wschodnim Feralas. Bez względu na los zaginionego kuriera zadanie dostarczenia paczki pozostaje niewykonane.$B$BDokładne oględziny paczki ujawniają odręcznie napisane na opakowaniu imię: „Falfindel Strażnik Szlaków”. Być może to on jest ostatecznym odbiorcą paczki.', 'Zanieś niedostarczoną paczkę Falfindelowi Strażnikowi Szlaków w Thalanaar.', '', '', '', '', '', '', 0),
(4401, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4464, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(4465, 'plPL', 'Skażony śpiewokwiat', '', '', '', 'Wróć do skażonego śpiewokwiatu w Spaczonej Kniei.', '', '', '', '', 0),
(5143, 'plPL', 'Garbarstwo plemienne', 'Nauka garbarstwa plemiennego wymaga zrozumienia, jak pierwotna jest naprawdę natura. Wiem, że $gopanowałeś:opanowałaś; już sztukę wyrobu dzikich skórzanych pancerzy, i jestem gotów dokończyć twoje szkolenie.$B$BWiedz jednak, $N: wybierając tę ścieżkę, zgadzasz się nigdy nie uczyć garbarstwa smoczołuskiego ani garbarstwa żywiołów – można praktykować tylko jedną z tych trzech sztuk. Co więcej, przynieś mi najlepsze okazy swoich dzikich skórzanych pancerzy. Od tego zaczniemy twoją drogę do mistrzostwa.', 'Przynieś dziką skórzaną kamizelkę i dziki skórzany hełm Caryssii Łowczyni Księżyca w Feralas.$B$BUkończenie tego zadania da ci dostęp do sztuki garbarstwa plemiennego.$B$BUkończenie tego zadania uniemożliwi ci naukę garbarstwa smoczołuskiego i garbarstwa żywiołów; zanim to zrobisz, upewnij się, że to ścieżka, którą chcesz podążać.', '', 'Wróć do Caryssii Łowczyni Księżyca w Tysiącu Filarów.', '', '', '', '', 0),
(7003, 'plPL', 'Porażone olbrzymy', 'Jeśli mam tu zostać, muszę coś zrobić z tymi olbrzymami! Na pewno nie są dobre dla interesów, prawda?$B$BPracuję nad odmianą gnomiego promienia zmniejszającego, ale przy jego budowie wykorzystuję wyższe osiągnięcia GOBLIŃSKIEJ techniki! Aby uniknąć niedogodności, takich jak moja własna śmierć, chciałbym, żebyś $gwypróbował:wypróbowała; go na dowolnych olbrzymach w Feralas. Po zmniejszeniu powinna na nich zostać pozostałość po miniaturyzacji – przynieś mi jej trochę!', 'Użyj Ultrapomniejszacza Zorbina, by porazić dowolnego olbrzyma w Feralas i zmienić go w bardziej poręczną postać. Przynieś 15 pozostałości po miniaturyzacji, znalezionych na porażonych olbrzymach, Zorbinowi Fandazzle\'owi przy przystani na Zapomnianym Wybrzeżu w Feralas.', '', 'Wróć do Zorbina Fandazzle\'a na Zapomnianym Wybrzeżu w Feralas.', '', '', '', '', 0),
(7441, 'plPL', 'Pusillin i starszy Azj\'Tordin', 'Opuściłem gardę tylko na jedną chwilę, $gnieznajomy:nieznajoma;. W pośpiechu, by wyrwać się z uścisku upadłego księcia, dałem się okraść. Najplugawszy z demonów, chochlik Pusillin, ukradł moją księgę inkantacji i klucz do niegdyś wspaniałych sal Eldre\'Thalas.$B$BKlucz już mnie nie interesuje, bo wymieniłem nieśmiertelność na wolność, ale rozpaczliwie potrzebuję mojej księgi inkantacji.$B$BZnajdź chochlika Pusillina i odzyskaj moją księgę.$B$BSzukaj Pusillina w Dzielnicy Wypaczonego Drzewa w Srogomłotach.', 'Udaj się do Srogomłotów i odnajdź chochlika Pusillina. Wszelkimi sposobami przekonaj Pusillina, by oddał ci księgę inkantacji Azj\'Tordina.$B$BJeśli odzyskasz księgę inkantacji, wróć do Azj\'Tordina w Pawilonie Lariss w Feralas.', '', 'Wróć do Azj\'Tordina w Feralas.', '', '', '', '', 0),
(7481, 'plPL', 'Elfie legendy', 'Przed kilkoma laty samotny elfi mistrz imieniem Kariel Winthalus uciekł ze zniszczonej ojczyzny, zabierając ze sobą kilka pradawnych elfich artefaktów.$B$BPoszukiwania zaginionego mistrza zawiodły nas z ruin Quel\'Thalas, przez Płonące Stepy i bezkresne morze, aż do Feralas.$B$BPodejrzewamy, że elf szukał schronienia w salach Eldre\'Thalas (miejsca znanego dziś jako Srogomłoty).$B$BMusisz go odnaleźć, $gposzukiwaczu:poszukiwaczko; przygód. Żywy czy martwy – wiedza, którą ze sobą niósł, musi zostać odzyskana!', 'Przeszukaj Srogomłoty w poszukiwaniu Kariela Winthalusa. Zamelduj się u mędrca Koroluska w Obozie Mojache z informacjami, jakie zdołasz zdobyć.', 'Mistrz Kariel Winthalus odnaleziony', 'Wróć do mędrca Koroluska w Obozie Mojache w Feralas.', '', '', '', '', 0),
(7482, 'plPL', 'Elfie legendy', 'Przed kilkoma laty samotny elfi mistrz imieniem Kariel Winthalus uciekł ze zniszczonej ojczyzny, zabierając ze sobą kilka pradawnych elfich artefaktów.$B$BPoszukiwania zaginionego mistrza zawiodły nas z ruin Quel\'Thalas, przez Płonące Stepy i bezkresne morze, aż do Feralas.$B$BPodejrzewamy, że elf szukał schronienia w salach Eldre\'Thalas (miejsca znanego dziś jako Srogomłoty).$B$BMusisz go odnaleźć, $gposzukiwaczu:poszukiwaczko; przygód. Żywy czy martwy – wiedza, którą ze sobą niósł, musi zostać odzyskana!', 'Przeszukaj Srogomłoty w poszukiwaniu Kariela Winthalusa. Zamelduj się u uczonej Runiczny Cierń w Warowni Lunopiórej z informacjami, jakie zdołasz zdobyć.', 'Mistrz Kariel Winthalus odnaleziony', 'Wróć do uczonej Runiczny Cierń w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(7488, 'plPL', 'Sieć Lethtendris', 'Magini Lethtendris, okrutna krwawa elfka, której brutalność dorównuje tylko jej chorobliwemu uzależnieniu od magii, uciekła do Srogomłotów. Stworzyła urządzenie – sieć do chwytania magicznej energii tego miejsca – i obawiamy się, że jeśli nikt jej nie powstrzyma, wyrządzi naszemu światu nieodwracalne szkody!$B$BPowstrzymaj ją, $N. Znajdź ją i odbierz jej sieć. Najpewniej przebywa w pobliżu satyrów w Dzielnicy Wypaczonego Drzewa w Srogomłotach. Przynieś mi sieć, żeby jej moc można było bezpiecznie uwolnić z powrotem w dziczy...', 'Przynieś sieć Lethtendris Latronicusowi Księżycowej Włóczni w Warowni Lunopiórej w Feralas.', '', 'Wróć do Latronicusa Księżycowej Włóczni w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(7489, 'plPL', 'Sieć Lethtendris', 'Krwawa elfka Lethtendris posunęła się za daleko. Tak bardzo pragnęła gromadzić magiczną moc, że sprzeciwiła się swoim pobratymcom i stworzyła urządzenie o podstępnej konstrukcji – sieć, która ma wysysać skażoną magiczną energię Srogomłotów. Nawet teraz gromadzi tę energię i zamierza uwolnić ją przeciw swoim wrogom.$B$BLethtendris trzeba powstrzymać. Znajdź ją w Dzielnicy Wypaczonego Drzewa w Srogomłotach, pokonaj ją i przynieś mi jej sieć, żeby można ją było przekazać do zbadania rozsądniejszym krwawym elfom.', 'Przynieś sieć Lethtendris Talo Cierniokopytowi w Obozie Mojache w Feralas.', '', 'Wróć do Talo Cierniokopyta w Obozie Mojache w Feralas.', '', '', '', '', 0),
(7721, 'plPL', 'Paliwo do porażania', 'Jeśli wbrew zdrowemu rozsądkowi zostanę tu i otworzę warsztat inżynieryjny na Zapomnianym Wybrzeżu, będę musiał się uporać z tymi natrętnymi żywiołakami. Przeklęte niech będą niekontrolowane moce żywiołów, powiadam!$B$BNa szczęście dla mnie – a teraz i dla ciebie, $gmój przyszły agencie prowokatorze:moja przyszła agentko prowokatorko; – żywiołaki są idealnym źródłem surowej mocy do udoskonalenia mojego Ultrapomniejszacza. Daj im popalić, powiadam! Tylko przy okazji pamiętaj, żeby zachować dla mnie rdzenie żywiołaków wody!', 'Zbierz 10 rdzeni żywiołaka wody z morskich żywiołaków i morskich bryzg na Zapomnianym Wybrzeżu w Feralas i przynieś je Zorbinowi Fandazzle\'owi, który przebywa przy tamtejszej przystani.', '', 'Wróć do Zorbina Fandazzle\'a na Zapomnianym Wybrzeżu w Feralas.', '', '', '', '', 0),
(7725, 'plPL', 'Znowu te porażone olbrzymy', 'Wiem, że już $gzebrałeś:zebrałaś; dla mnie pozostałość... ale jeśli najdzie cię ochota na bis tej wesołej zabawy, zawsze przyda mi się więcej pozostałości.$B$BChoć tym razem nie mogę zaoferować aż tak sowitej zapłaty, z przyjemnością rozgłoszę wieść o twojej przysłudze wszystkim moim goblińskim przyjaciołom, którzy mają uszy.$B$BWierz mi, $gpanie:pani;, te gobliny mają naprawdę duże uszy.', 'Użyj Ultrapomniejszacza Zorbina, by porazić dowolnego olbrzyma w Feralas i zmienić go w bardziej poręczną postać. Przynieś 10 pozostałości po miniaturyzacji, znalezionych na porażonych olbrzymach, Zorbinowi Fandazzle\'owi przy przystani na Zapomnianym Wybrzeżu w Feralas.', '', 'Wróć do Zorbina Fandazzle\'a na Zapomnianym Wybrzeżu w Feralas.', '', '', '', '', 0),
(7726, 'plPL', 'Więcej paliwa do porażania', 'Więcej pracy, powiadasz? Czy moja heroiczna misja zbierania kawałków mazi z wnętrza żywiołowych istot nie ugasiła twojego pragnienia przygód? Może więcej tego samego na próżno spróbuje zapełnić bezdenną studnię twojej żądzy zadań...$B$BDobra, dość melodramatu – naprawdę potrzebuję więcej rdzeni żywiołaków wody. Rozpaczliwie próbuję rozkręcić tu interes, więc nagrody nie będą tak duże... ale obiecuję, że powiem każdemu w zasięgu słuchu, jak mi $gpomogłeś:pomogłaś;. Zaufaj mi – znam ludzi w Kartelu!', 'Zbierz 6 rdzeni żywiołaka wody z morskich żywiołaków i morskich bryzg na Zapomnianym Wybrzeżu w Feralas i przynieś je Zorbinowi Fandazzle\'owi, który przebywa przy tamtejszej przystani.', '', 'Wróć do Zorbina Fandazzle\'a na Zapomnianym Wybrzeżu w Feralas.', '', '', '', '', 0),
(7730, 'plPL', 'Plaga Zukk\'ash', 'Z tego, co zdołali ustalić nasi zwiadowcy, sądzimy, że wróg na południe od gnoli to rasa podobna do owadów. Szczerze mówiąc, nie ma znaczenia, czy są rozumni. Jeśli to oni doprowadzają gnole do szału przeciwko nam, to stanowią równie duże zagrożenie jak gnole – jeśli nie większe.$B$BWedrzyj się głęboko tam, gdzie żyją te owady Zukk\'ash; to miejsce nazywa się Wijącą się Głębią. Przetrzeb ich szeregi i zdaj mi raport z tego, co znajdziesz, a jako dowód swojej roboty przynieś ich pancerze.', 'Przynieś 20 pancerzy Zukk\'ash Hadokenowi Rączemu Krokowi w Obozie Mojache w Feralas.', '', 'Wróć do Hadokena Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(7731, 'plPL', 'Żądłobicz', 'Podczas zwiadu w Wijącej się Głębi jeden z naszych zwiadowców doniósł, że widział olbrzymiego owada – znacznie większego od innych dostrzeżonych owadów – który krążył po poskręcanym terenie. Nie dość, że jest większy, to jeszcze zdaje się roztaczać jakąś aurę, której inne owady nie mają. Nadaliśmy mu imię – Żądłobicz.$B$BWnętrzności tej bestii byłyby bezcenne do badań, gdy będziemy szukać najlepszego sposobu na rozprawienie się z tym nowym zagrożeniem. Wytnij jej gruczoły wydzielnicze i natychmiast mi je przynieś!', 'Pokonaj Żądłobicza w Wijącej się Głębi i przynieś jego gruczoły Hadokenowi Rączemu Krokowi w Obozie Mojache w Feralas.', '', 'Wróć do Hadokena Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(7733, 'plPL', 'Lepsza jakość', 'Mam trop na jeszcze LEPSZE źródło skór, choć trudno w to uwierzyć! W północnej części Feralas – głęboko w Warowni Szramy Wściekłości – żyje kolejne stado yeti. Są znacznie twardsze niż te, z którymi $gmiałeś:miałaś; do czynienia wcześniej, więc jeśli jesteś $ggotów:gotowa; na większe wyzwanie, lepiej miej się na baczności!$B$BSowicie cię wynagrodzę za dziesięć ich skór; przynieś mi je tutaj, a dobijemy targu.', 'Przynieś 10 skór yeti Szramy Wściekłości Prattowi McGrubbenowi w Warowni Lunopiórej w Feralas.', '', 'Wróć do Pratta McGrubbena w Warowni Lunopiórej w Feralas.', '', '', '', '', 0),
(7734, 'plPL', 'Lepsza jakość', 'Mam trop na jeszcze LEPSZE źródło skór, choć trudno w to uwierzyć! W północnej części Feralas – głęboko w Warowni Szramy Wściekłości – żyje kolejne stado yeti. Są znacznie twardsze niż te, z którymi $gmiałeś:miałaś; do czynienia wcześniej, więc jeśli jesteś $ggotów:gotowa; na większe wyzwanie, lepiej miej się na baczności!$B$BSowicie cię wynagrodzę za dziesięć ich skór; przynieś mi je tutaj, a dobijemy targu.', 'Przynieś 10 skór yeti Szramy Wściekłości Jangdorowi Rączemu Krokowi w Obozie Mojache w Feralas.', '', 'Wróć do Jangdora Rączego Kroku w Obozie Mojache w Feralas.', '', '', '', '', 0),
(7735, 'plPL', 'Nieskazitelna skóra yeti', '$GZnalazłeś:Znalazłaś; nieskazitelną skórę yeti, wyjątkowo grubą i mocną – nawet bardziej niż te, które $gwidziałeś:widziałaś; u yeti z Warowni Szramy Wściekłości.$B$BSkoro Pratt McGrubben z Warowni Lunopiórej skupuje skóry yeti, ta może go szczególnie zainteresować.', 'Zanieś nieskazitelną skórę yeti Prattowi McGrubbenowi w Warowni Lunopiórej w Feralas.', '', '', '', '', '', '', 0),
(7738, 'plPL', 'Doskonała skóra yeti', '$GZnalazłeś:Znalazłaś; coś, co może być doskonałą skórą yeti. Od razu widać, że jest wyjątkowo gruba i mocna – nawet bardziej niż te, które $gwidziałeś:widziałaś; u yeti z Warowni Szramy Wściekłości.$B$BSkoro Jangdor Rączy Krok z Obozu Mojache skupuje skóry yeti, ta może go szczególnie zainteresować.', 'Zanieś doskonałą skórę yeti Jangdorowi Rączemu Krokowi w Obozie Mojache w Feralas.', '', '', '', '', '', '', 0),
(8679, 'plPL', 'Nestor Ponury Totem', '', '', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(2523, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(2766, 'plPL', 'Umieszczasz jajo... to znaczy sygnalizator alarmowy... w kurczaku... to znaczy w samonaprowadzającym robocie.$b$bZ wnętrza robota dobiega buczenie i warkot, gdy próbuje on stanąć na nogi. Kiedy robot ożywa, znów słychać głos Oglethorpe\'a, ale tym razem z wnętrza robota:$b$b„OOX-22/FE przynajmniej działa, ale wymaga poważnych napraw! Jest o wiele za ciężki, żebyś $gmógł:mogła; go nieść... ale chyba mam pewien pomysł. Popilnujesz go jeszcze trochę?”', 0),
(2821, 'plPL', '$GPrzyjrzałeś:Przyjrzałaś; się fakturze tych skór? Odpowiednio wyprawione mogą być nawet mocniejsze od żelaza. Niewielu ludzi o nich wie, a to w połączeniu z mnóstwem znanych mi sposobów wyprawiania pozwoli mi być może tworzyć przedmioty z prawdziwym znakiem jakości... oczywiście dzięki tobie!$B$BA teraz wybierz, proszę, coś spośród tego, co mogę ci zaoferować za twoją pomoc!', 0),
(2822, 'plPL', 'Ach, wspaniale! Mówię ci, te skóry, odpowiednio wyprawione, są wytrzymałe jak żelazo! Wiele prób zajmie mi dobranie właściwej mieszanki do garbowania, ale jestem pewien, że wzniosą mój znak jakości na wyższy poziom.$b$bA co do ciebie, $N... twoja pomoc okazała się dla mnie bezcenna. Wybierz, proszę, któryś z wykonanych przeze mnie przedmiotów.', 0),
(2844, 'plPL', 'Och, tak się cieszę, że mnie $gznalazłeś:znalazłaś;! Muszę przyznać, że trochę się zgubiłam... Ale czyż to nie piękne miejsce?', 0),
(2845, 'plPL', 'Co? Mówisz, że ten dzwonek zadziała, jak Shay znowu ucieknie? No proszę!$B$BSkoro tyle dla mnie $gzrobiłeś:zrobiłaś;, masz, $N.', 0),
(2847, 'plPL', 'No cóż, $N, cieszę się, że jesteś z nami. Jako $ggarbarz:garbarka; $gpodjąłeś:podjęłaś; mądrą decyzję. Noszący skórzane zbroje będą się o ciebie zabijać, gdy tylko nauczysz się wytwarzać którąkolwiek część dzikiej skórzanej zbroi.$B$BBierzmy się do pracy – od czego chcesz zacząć?', 0),
(2848, 'plPL', 'Te zestawy pancerne są solidnej jakości, $N. Jeśli czegoś wymagam nie tylko od swojej pracy, ale i od pracy tych, których zatrudniam, to właśnie jakości.$B$BDobrze się $gspisałeś:spisałaś; i $gzasłużyłeś:zasłużyłaś; na ten wykrój. Mam nadzieję, że przyniesie ci tyle korzyści, ile przyniósł mnie.', 0),
(2849, 'plPL', 'To bardzo ładne wyroby, $N. Za sam kunszt i staranność, z jaką je wykonano, można by dostać kilka srebrników więcej niż za przeciętną rzecz.$B$B$GZrealizowałeś:Zrealizowałaś; moje zamówienie, a za to należy ci się nagroda. Wiedza o wytwarzaniu dzikich skórzanych kamizelek jest teraz twoja!', 0),
(2850, 'plPL', 'Ten ekwipunek nocnego pejzażu, który $gdostarczyłeś:dostarczyłaś;, idealnie spełnia warunki zamówienia, $N. Niczego mniej nie oczekuję od $ggarbarza:garbarki; twojego formatu.$B$BBez wątpienia $gzasłużyłeś:zasłużyłaś; na ten wykrój. Daję ci go bez zastrzeżeń i mam nadzieję, że odpowiednio na nim skorzystasz.', 0),
(2851, 'plPL', 'Po raz kolejny $gzrealizowałeś:zrealizowałaś; złożone zamówienie z wprawą $gdoświadczonego fachowca:doświadczonej fachowczyni;. $GZasłużyłeś:Zasłużyłaś; na ten wykrój, a także na moje podziękowania.', 0),
(2852, 'plPL', 'Znów $gzrealizowałeś:zrealizowałaś; zamówienie bez zarzutu. Może pewnego dnia to ja przyjdę do CIEBIE po wiedzę, co, $N?$B$BOto wykrój na nogawice, a do tego moje podziękowania. Zachowaj tę wiedzę w pamięci i niech twoje gotowe wyroby czerpią z twoich imponujących umiejętności!', 0),
(2854, 'plPL', 'No cóż, $N, cieszę się, że $gzostałeś moim uczniem:zostałaś moją uczennicą;. Jako $ggarbarz:garbarka; $gpodjąłeś:podjęłaś; mądrą decyzję. Ci, którzy używają skórzanych zbroi, będą się o ciebie zabijać, gdy tylko opanujesz sztukę dzikiej skóry.$b$bBierzmy się do pracy – od czego chcesz zacząć?', 0),
(2855, 'plPL', 'Te zestawy pancerne są solidnej jakości, $N. Jeśli czegoś wymagam nie tylko od swojej pracy, ale i od pracy tych, których uczę, to właśnie jakości.$b$bDobrze się $gspisałeś:spisałaś; i $gzasłużyłeś:zasłużyłaś; na ten wykrój. Mam nadzieję, że przyniesie ci tyle korzyści, ile przyniósł mnie.', 0),
(2856, 'plPL', 'To bardzo ładne wyroby, $N. Kunszt i staranność, z jaką je wykonano, pokazują, że $gpostanowiłeś:postanowiłaś; w pełni poświęcić się tym zadaniom.$b$b$GSpełniłeś:Spełniłaś; moje prośby, a za to należy ci się nagroda. Wiedza o wytwarzaniu dzikich skórzanych kamizelek jest teraz twoja!', 0),
(2857, 'plPL', 'Ten ekwipunek nocnego pejzażu, który $gdostarczyłeś:dostarczyłaś;, idealnie spełnia postawione ci wymagania, $N. Niczego mniej nie oczekuję od $ggarbarza:garbarki; twojego formatu.$b$b$GZasłużyłeś:Zasłużyłaś; na zaszczyt wytwarzania dzikich skórzanych hełmów. Daję ci ten wykrój bez zastrzeżeń i mam nadzieję, że odpowiednio na nim skorzystasz.', 0),
(2858, 'plPL', 'Po raz kolejny $gwykonałeś:wykonałaś; przedmioty z wprawą $gdoświadczonego fachowca:doświadczonej fachowczyni;. $GZasłużyłeś:Zasłużyłaś; na ten wykrój, a także na moje gratulacje.', 0),
(2859, 'plPL', 'Znów $gwykonałeś:wykonałaś; moje zadanie bez zarzutu. Może pewnego dnia to ja przyjdę do CIEBIE po wiedzę, co, $N?$b$bOto wykrój na nogawice, a do tego moje podziękowania. Zachowaj tę wiedzę w pamięci i niech twoje gotowe wyroby czerpią z twoich imponujących umiejętności!', 0),
(2862, 'plPL', 'To dowód dobrego początku, $N. Twoje umiejętności żołnierskie zasługują na pochwałę.$B$BNie tylko ciebie proszę o to zadanie. Wielu przed tobą z nimi walczyło i w przeszłości nasze wysiłki trzymały je na dystans. Ostatnio jednak znacznie częściej próbują przeć na północ, na nasze ziemie. Ich ataki stały się też bardziej dzikie... niemal jakby działały z desperacji.$B$BMam jednak plan, $N, który może raz na zawsze rozstrzygnąć sprawę z nimi...', 0),
(2863, 'plPL', '$GZrobiłeś:Zrobiłaś;, o co prosiłem, i za to ci salutuję. Przyjmij tę skromną nagrodę jako rekompensatę za twój trud, $N.$B$BSkoro ich szeregi się przerzedziły, a przywódcy zginęli, gnole dwa razy się zastanowią, zanim zaatakują obóz. To jednak nie kończy sprawy...$B$BMusi być jakiś powód, dla którego gnole wpadły w taki szał. Zanim zdążą się przegrupować, chcę się dowiedzieć, co go wywołuje.', 0),
(2866, 'plPL', 'Oględziny altany ujawniają kilka ciekawych i nietypowych rzeczy, które odróżniają ją od otaczających ruin.$B$BPo pierwsze, altana najwyraźniej powstała później niż inne budowle w ruinach. Po drugie, na jej bokach wyryto niewielki ciąg glifów. Glify powtarzają się według wzoru, ale ich pochodzenie i znaczenie pozostają nieznane. Po trzecie, sam kamień altany jest ciepły w dotyku.$B$BTo bez wątpienia można uznać za coś, co „zwraca uwagę” podczas przeszukiwania ruin!', 0),
(2867, 'plPL', 'Witaj z powrotem, $N. Twój raport o tej altanie jest wielce... niepokojący. Wygląda na to, że nawet jeśli tamtejsze nagi nie planowały ataku, ich dalsza obecność źle wróży naszej ekspansji w Feralas. Tak czy inaczej, oto zapłata za twoje zbadanie sprawy.$B$BWygląda na to, że Warownia Lunopiórej pilnie potrzebuje dodatkowej pomocy w sprawie nag Nienawistnego Grzebienia. Chciałabym powierzyć ci to zadanie, jeśli masz ochotę. Jest wiele do zrobienia.', 0),
(2869, 'plPL', 'Tak, tak, te łuski są aż nadto zadowalające. Właściwie chyba wyślę je Prattowi, żeby im się przyjrzał. Może zdoła zrobić z nich coś użytecznego.$B$BA co do ciebie, mam kolejną misję, na którą chcę cię wysłać. Ale najpierw oto twoja nagroda za łuski. Twoja nieustająca służba dla generał i całej Warowni Lunopiórej to błogosławieństwo w obliczu przeciwności.', 0),
(2870, 'plPL', 'Dobra robota, $N! Śmierć lorda Shalzaru na jakiś czas pogrąży nagi w chaosie, jeśli nie na zawsze. Zagrożenie z ich strony jest teraz bardziej pod naszą kontrolą niż kiedykolwiek i zawdzięczamy to tobie.$B$BOto kolejna nagroda ze skarbca warowni – $gzasłużyłeś:zasłużyłaś; na każdego miedziaka. Ty i twoi bliscy jesteście zawsze mile widziani w Warowni Lunopiórej, $gprzyjacielu:przyjaciółko;.$B$BJeszcze jedno, zanim odejdziesz, $N... jeśli $gmógłbyś:mogłabyś;...', 0),
(2871, 'plPL', 'Ciekawe... mówisz, że to pochodzi z Ruin Solarsal? Cóż, Latro ma rację, że muszę się temu przyjrzeć. Na pierwszy rzut oka nie wygląda na coś, co pochodzi z tych ruin. Z drugiej strony nie jest to też dzieło nag... nie coś tak obcego.$B$BZbadanie tego przedmiotu zajmie trochę czasu. Gdy skończę badania, może skorzystam z twoich talentów, jeśli będziesz w pobliżu.$B$BProszę, weź jedną z tych rzeczy, które mamy na zbyciu. Mam nadzieję, że się przyda!', 0),
(2878, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(2879, 'plPL', 'Utrzymanie zasilonego kostura w dłoniach jest niemal niemożliwe. Jego moc dudni w całym twoim ciele.$B$BSięgasz ku zimnej powierzchni Monolitu Equinex...$B$BOtwierają się małe drzwiczki, przez które możesz sięgnąć do środka i wyjąć artefakt.$B$BPromienie światła wypełniają przestrzeń wokół Monolitu Equinex.', 0),
(2902, 'plPL', 'Po obejrzeniu mapy okazuje się, że to plany bitewne, na których zależy Hadokenowi Rączemu Krokowi. Na mapie narysowano liczne strzałki, które być może oznaczają ruchy oddziałów, ale większość z nich zdaje się prowadzić na południe, a nie na północ, gdzie leży Obóz Mojache.$B$BNa innym fragmencie mapy jest rysunek czegoś, co uznajesz za jakiegoś wielkiego owada, a pod nim rozmaite kreski. Sądząc po gnolach, mogą one oznaczać ich straty w walce z nieznanymi robakami...', 0),
(2903, 'plPL', 'Ach, właśnie tego potrzebowaliśmy. Choć nie jestem biegły w odcyfrowywaniu większości bazgrołów na tej mapie, widziałem w życiu dość planów bitewnych, by zrozumieć, co się dzieje z gnolami. Wygląda na to, że obecnie walczą na dwóch frontach. Jeden to my... ale wydaje się, że główne siły kierują przeciw wrogowi na południu.$B$BKryje się tu więcej, niż widać na pierwszy rzut oka. Może czas się dowiedzieć, kim naprawdę jest ten drugi wróg.', 0),
(2942, 'plPL', 'Czytałem, odkąd $godszedłeś:odeszłaś;, $N. Kamień, który $gznalazłeś:znalazłaś;, nazywa się Kamieniem Jutra. Choć nie jestem jeszcze do końca pewien, do czego służy, możesz być $gpewien:pewna;, że to coś niezwykle ważnego, skoro ukryto go w Monolicie Equinex w taki sposób.$B$BBędę kontynuował badania i mam nadzieję, że w przyszłości będę mógł na ciebie liczyć, $N. Dziękuję za całą twoją pomoc.', 0),
(2969, 'plPL', 'Dzięki niech będą Elunie, $N! Jesteś wielkim błogosławieństwem dla nas i dla duszkowców, które $guratowałeś:uratowałaś;. Jer\'kai i ja nigdy nie zdołałybyśmy same pomóc smokom. Twoja interwencja w sprawy Ponurego Totemu zostanie zapamiętana.$B$BPorozmawiaj teraz z Jer\'kai... Muszę przygotować się do odwetu. To, że baśniowe smoki są wolne, nie znaczy, że takie pozostaną. Jer\'kai i ja przechodzimy teraz do ofensywy.', 0),
(2970, 'plPL', 'Kindal miała co do ciebie rację, $N – naprawdę masz do tego smykałkę. Masz więcej doświadczenia w przygodach niż my obie i za to ci dziękujemy.$B$BKlan Ponurego Totemu jest znacznie bardziej wrogi niż większość taurenów... Ciekawe, czy ich własny lud krzywo patrzy na ich postępki. Nie zdziwiłabym się. Jak zapewne wiesz, wiele ras Azeroth ma powiązania z mniej życzliwymi pobratymcami.$B$BAle to rozmowa na inny dzień.', 0),
(2973, 'plPL', 'Wspaniale, $N! Świetnie się nadadzą. Wystarczy ich na płaszcz dla Korrin, a może i na więcej! Dziękuję.$b$bMam nadzieję, że wyprawa nie była zbyt niebezpieczna? Feralas nie słynie z łagodności, ale najwyraźniej $gporadziłeś:poradziłaś; sobie całkiem nieźle.$b$bJeszcze raz dziękuję, $N.', 0),
(2974, 'plPL', 'To dobre rogi, $N. Dobra robota. Wezmę je od ciebie i na pewno powiem o tym Belgromowi, gdy tylko wrócimy do Orgrimmaru. $GPomogłeś:Pomogłaś; mi już dwa razy i za to masz moje uznanie. Może kiedyś to ja będę mógł ci pomóc! Powodzenia.', 0),
(2975, 'plPL', 'Doskonale, $N. Z czasem ziemia się zagoi. Nie wolno nam się poddawać.', 0),
(2978, 'plPL', 'Ten zwój... $GZnalazłeś:Znalazłaś; go w Posterunku Gordunni?', 0),
(2979, 'plPL', 'Ta kula da nam więcej informacji o Gordunni... które wykorzystamy, planując ich upadek, $N.', 0),
(2980, 'plPL', '$GOkazałeś:Okazałaś; się $gzaufanym i niezawodnym sojusznikiem:zaufaną i niezawodną sojuszniczką;, $N.', 0),
(2982, 'plPL', 'Jestem ci bardzo wdzięczna, że $gzdołałeś:zdołałaś; to dla mnie zrobić.$B$BA teraz, proszę, ani słowa o tym Troyasowi...', 0),
(2987, 'plPL', 'Doskonale! Zabiorę je ze sobą w dalszą podróż, $N. Na pewno znajdę kogoś, kto słono zapłaci za ten kobalt.$b$bMasz, weź to za fatygę.', 0),
(3062, 'plPL', 'Teraz wiem, że Edana naprawdę nie żyje. To serce... zachowam je na pamiątkę tego, co tu dla mnie $gzrobiłeś:zrobiłaś;, $N. Dziękuję.', 0),
(3063, 'plPL', 'Dziękuję, $N. Dzięki tobie stary tauren zaznał spokoju.', 0),
(3121, 'plPL', 'Czekałem, aż Uzer\'i to dostarczy...$b$bPozwól, że dam ci mieszankę ziół, którą przygotowałem na jego... cóż, eksperymenty...', 0),
(3122, 'plPL', 'Właśnie tego potrzebuję, żeby przygotować naczynie na muisek, $N. Wkrótce się przekonamy, czy moje najnowsze inkantacje są tak potężne, jak się spodziewałem.$b$bChwileczkę, proszę. Muszę odprawić rytuał i użyć ziół.', 0),
(3123, 'plPL', 'Gdy stworzenie ginie gwałtowną śmiercią, jego muisek może uciec i szukać zemsty. Pomniejszenie stworzeń, tak jak to $gzrobiłeś:zrobiłaś;, $N, nie pozwala muisek uciec. Teraz możemy go używać, jak nam się podoba!', 0),
(3124, 'plPL', 'Gdybyśmy po zabiciu zwierzęcia pozwolili uciec jego muisek, mógłby przybrać postać jeszcze potężniejszego stworzenia. Nigdy nie bylibyśmy bezpieczni przed jego zemstą.$b$bDałem ci niebezpieczne zadanie, $N. I znów dobrze się z niego $gwywiązałeś:wywiązałaś;.', 0),
(3125, 'plPL', 'Dziękuję, $N. Teraz duchowe moce baśniowego smoka będą w naszym zasięgu.$b$bMam nadzieję, że zechcesz wykonać dla mnie kolejne zadanie.', 0),
(3126, 'plPL', 'Dziękuję, $N. Nasza kolekcja muisek jest prawie kompletna.', 0),
(3127, 'plPL', 'Wyobraź sobie tylko, jakie możliwości daje nam to, co teraz posiadamy, $N. Wraz z zebranymi przez ciebie materiałami będę mógł na zawsze uwięzić muisek tych stworzeń w czymkolwiek zechcę.', 0),
(3128, 'plPL', 'Doskonale! Te materiały w połączeniu z muisek powinny dać dokładnie takie wyniki, jakich pragnęliśmy.', 0),
(3129, 'plPL', 'Zgodnie z obietnicą możesz wybierać, $N. Muisek stworzeń został na zawsze zamknięty w mocy tej broni.$b$bMożesz teraz władać ich energią jak własną. Używaj jej dobrze.', 0),
(3130, 'plPL', 'Doskonale, $N – u tych, z którymi pracuję, cenię postawę „da się zrobić”.$B$BGenerał Lunopióra powierzyła mi bezpośrednie rozprawienie się z nagami. Mój plan ma dwa cele: po pierwsze, osłabimy ich siły zarówno liczebnie, jak i pod względem dowodzenia, a po drugie, odkryjemy, co knują w ruinach. Z twoją pomocą przeciwstawimy się nagom, nie narażając ogólnego bezpieczeństwa warowni.', 0),
(3363, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(3380, 'plPL', 'Tak, Zatopiona Świątynia – mogę powiedzieć, że widziałem ją na własne oczy. Może chcesz usłyszeć o niej więcej?$b$bWyglądasz na $gamatora:amatorkę; przygód – wiem rzeczy, które mogą cię zaciekawić...', 0),
(3445, 'plPL', 'Tak, Zatopiona Świątynia – mogę powiedzieć, że widziałem ją na własne oczy. Może chcesz usłyszeć o niej więcej?$b$bWyglądasz na $gamatora:amatorkę; przygód – wiem rzeczy, które mogą cię zaciekawić...', 0),
(3567, 'plPL', 'Chcesz podziwiać widok ze szczytu jednego z Bliźniaczych Kolosów? Mogę cię tam wysłać.$B$BZastanów się jednak, jak zejdziesz na dół. To podróż tylko w jedną stronę.', 0),
(3791, 'plPL', 'Uch, przez to jutroziarno czuję się... dziwnie. Na Elunę, co ten Jeleniorogi z nim wyprawia?$B$BTak czy inaczej, jeszcze raz dziękuję za pomoc. Proszę, drobiazg... no wiesz, za fatygę. Moje badania nad jutroziarnem trochę potrwają i bez wątpienia będę potrzebował go więcej. Przy okazji mogę chyba sprawdzić, czy jutroziarno ma jakieś istotne zastosowania alchemiczne. Mimo to czuję się nieswojo nawet w jego pobliżu.', 0),
(3792, 'plPL', 'Dzięki, $N; na razie odłożę je na bok. Choć nie dysponuję takimi zasobami jak Jeleniorogi, mogę ci dać drobiazg za fatygę. Tak czy inaczej, kto wie, co się stanie, jeśli Jeleniorogi będzie dalej gromadził jutroziarno za jutroziarnem. Coś tu śmierdzi, zapamiętaj moje słowa.$B$BPamiętaj, że zawsze chętnie przyjmę więcej jutroziarna. Biorę je po pięć sztuk naraz.', 0),
(4041, 'plPL', 'No proszę, $gwykiwałeś:wykiwałaś; starego Miblona, co?', 0),
(4113, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4114, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4116, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4118, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4120, 'plPL', 'Z twoich opisów wynika, że te stworzenia przejawiają bezmyślną zajadłość...$b$bMiej się na baczności, $N. W twoim najlepszym interesie jest dowiedzieć się więcej o skażeniu. Zawsze poznaj swojego wroga.', 0),
(4124, 'plPL', 'Zakładam, że przysłał cię Latro. Choć uważam, że to już przegrana sprawa, przyjmę każdą pomoc, jaką możesz zaoferować. Muszę przyznać... ulży mi, gdy wreszcie będę mógł zamknąć tę sprawę. Każdego dnia wyruszam w dzikie ostępy Feralas, szukając śladów Raschala, i każdej nocy wracam, nie mając nic do pokazania poza zębami gnoli i rozczarowaniem.', 0),
(4125, 'plPL', 'Znajdujesz coś, co wygląda na rozbitą łódź wiosłową. Przez lekko mętną wodę widzisz ziejące dziury w lewej burcie; z łodzi został niemal sam prosty drewniany szkielet. Cokolwiek ją rozbiło, najpewniej próbowało przełamać ją na pół. Na prawej burcie namalowano niewielki herb Warowni Lunopiórej.$B$BW mule u podstawy łodzi coś metalicznego błyska i przykuwa twój wzrok...', 0),
(4127, 'plPL', 'Ciekawe... Wydaje mi się, że to nóż Raschala. Mówisz, że $gznalazłeś:znalazłaś; go na dnie, obok jego łodzi? Cóż, sam nóż może nie wystarczyć, by powiązać go ze zniknięciem Raschala; mamy jednak do dyspozycji niekonwencjonalny sposób, by spróbować dowiedzieć się więcej.$B$B$GSłyszałeś:Słyszałaś; kiedyś o psychometrii?', 0),
(4129, 'plPL', 'Dziękuję, $N.$B$BChoć psychometria w żadnym razie nie jest nauką ścisłą, w przeszłości pozwalała mi wejrzeć w sytuacje, które inni uznali już za przegrane. Myślę, że jeśli użyję jej na nożu, który $godnalazłeś:odnalazłaś;, zobaczymy choć przebłysk tego, co spotkało Raschala.$B$BZajmie to tylko chwilę, ale nie nazwałbym tego zadaniem przyjaznym dla rzucającego. Uzbrój się w cierpliwość.', 0),
(4130, 'plPL', 'Dzięki, że $gprzekazałeś:przekazałaś; mi wizje Quinta, $N. Postaram się pamiętać, żeby następnym razem przy kartach być dla niego trochę łagodniejszym.$B$BRaschal potrafi o siebie zadbać w walce, a gnole nie są niczym, co mogłoby go zmartwić – ba, przerazić. Mimo to może ty i twoi towarzysze zdołacie wykorzystać te nowe informacje i dokonać przełomu, którego tak rozpaczliwie potrzebujemy.', 0),
(4131, 'plPL', 'Na pobliskim drzewie wiszą przybite dwa duże skórzane plecaki. Na przodzie każdego widnieje małe godło Warowni Lunopiórej...', 0),
(4135, 'plPL', 'Odkrywasz wielką kapsułę obcego pochodzenia. Jej powierzchnia wydaje się śluzowata, choć tu i ówdzie sterczą z niej stwardniałe narośla. Kapsuła jest tak wysoka i szeroka, że z łatwością zmieściłaby w sobie humanoida... a po słabym, humanoidalnym kształcie widocznym przez jej powłokę wnioskujesz, że rzeczywiście tak jest.', 0),
(4142, 'plPL', 'Krwawopłatek, co? Hmmm... No, lepiej wyjaśnij mi plan, a wtedy powiem ci, czy mogę pomóc.', 0),
(4143, 'plPL', 'Przyznaję, trochę się waham, czy dotykać tego paskudztwa, $N! Ale skoro Gregan mówi, że zadziała, to jestem gotów spróbować!', 0),
(4265, 'plPL', 'Witaj w domu, $N. Raschal zameldował się przed chwilą i opowiedział mi, co się stało.$B$BJa... nie, cała warownia nie jest w stanie dość ci podziękować za ten wielki czyn; Raschal by zginął, gdyby nie twoja pomoc w porę, a $gpomogłeś:pomogłaś; nam, nie wspominając nawet szeptem o najemniczej zapłacie. Nosisz znamię $gprawdziwego bohatera:prawdziwej bohaterki;. Wiedz, że w Ginro Rozpalaczu Ogniska zawsze będziesz mieć przyjaciela.', 0),
(4266, 'plPL', '$N, z całego serca dziękuję ci za pomoc, której nam $gudzieliłeś:udzieliłaś;. Twoja odwaga w obliczu przytłaczającej przewagi zasługuje na nagrodę tysiąc razy większą. Mimo to mam nadzieję, że przyjmiesz to w imieniu całej warowni.$B$BA teraz, jeśli pozwolisz... chciałabym jeszcze raz poprosić cię o pomoc. W świetle odkrycia roju Zukk\'ash tu, w Feralas, uważam, że jesteś $gnajlepszym kandydatem:najlepszą kandydatką; do tej misji.', 0),
(4281, 'plPL', 'Chwała Elunie, dostawa z Warowni Lunopiórej wreszcie dotarła!$b$bTwoja obecność tutaj podpowiada mi, że Raschala, naszego stałego kuriera, mógł spotkać zły los. Mam nadzieję, że wszystko dobrze się skończy. Wiem, że ostatnio Drzewne Łapy są mocno wzburzone przez coś, co jest na południe od nich. Może zginął tam, w dziczy; na twoim miejscu uważałbym, $gprzyjacielu:przyjaciółko;.$b$bTak czy inaczej, jeszcze raz dziękuję. Oto zapłata za dostarczenie tej paczki.', 0),
(4401, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4464, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(4465, 'plPL', 'Nakładasz na śpiewokwiat trochę cenariońskiej maści dla roślin. Natychmiast zaczyna zrzucać skażoną postać i rozkwita w pełną życia, zdrową roślinę.', 0),
(7003, 'plPL', 'Wyśmienitastycznie! Nie dość, że cieszę się z twojego powrotu z pozostałością, to jeszcze ze wszystkimi ważniejszymi kończynami na miejscu! To znaczy, no, przecież używanie Ultrapomniejszacza nigdy nie groziło żadnym niebezpieczeństwem, prawda?$B$BNaprawdę doceniam twój wysiłek w moim imieniu, $N. Doprawdy, jesteś $gprzyjacielem:przyjaciółką; goblinów na całym świecie. Przyjmij to w dowód mojej wdzięczności!', 0),
(7441, 'plPL', '$GZnalazłeś:Znalazłaś; ją! Niech będzie przeklęty ten nędzny chochlik. Niestety, moje doczesne dobra są w najlepszym razie skromne. Możesz wybrać spośród tego, co mam do zaoferowania.', 0),
(7481, 'plPL', 'Szkoda... prawdziwa tragedia. Mówisz, że przedmioty przepadły? Nie ma po nim śladu, tak?', 0),
(7482, 'plPL', 'Szkoda... prawdziwa tragedia. Mówisz, że przedmioty przepadły? Nie ma po nim śladu, tak?', 0),
(7488, 'plPL', '$GOdzyskałeś:Odzyskałaś; sieć! Dobra robota, $N! Lethtendris, jak wiele elfów jej pokroju, była ślepa na niebezpieczeństwa, jakie nadużywanie magii może ściągnąć na nasz świat. Wierzą, że są panami magii; nie zdają sobie sprawy, że są niewolnikami własnego nałogu. Jej śmierć mnie smuci, ale była konieczna.$B$BDziękuję, $N. Każę bezpiecznie uwolnić energię z sieci na rozległym obszarze, a potem zniszczę sieć, by zapobiec przyszłym magicznym nadużyciom.', 0),
(7489, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Ta sieć kryje w sobie ogromne zasoby magii Srogomłotów i boję się pomyśleć, jakie szkody mogłyby powstać, gdyby tę energię okiełznał ktoś tak nieodpowiedzialny jak Lethtendris. Smuci mnie jej śmierć, ale wiem, że za życia nigdy nie rozstałaby się ze swoją siecią.$b$bDziękuję, $N. Wyślę sieć adeptom magii bardziej odpowiedzialnym niż Lethtendris. To oni staną się nowymi strażnikami jej mocy.', 0),
(7721, 'plPL', 'Superbombowo-rewelacyjnie! Te rdzenie wystarczą mi do pracy na jakiś czas. Do tego wzdłuż wybrzeża jest teraz mniej żywiołaków, więc może przestanę płakać do poduszki na myśl, że otworzyłem interes w chyba najgorszym miejscu, jakie można sobie wyobrazić!$B$BDziękuję ci, $N, za twój wysiłek w moim imieniu. Choć to mocno nadwyręża moje finanse, pozwól, że okażę ci wdzięczność w sposób, który na pewno zrozumiesz i docenisz... łupy!', 0),
(7725, 'plPL', 'Niewyobrażalnie fantastycznie, $N! Znów mnie nie $gzawiodłeś:zawiodłaś; i za to ci dziękuję.$B$BDziękuję!$B$BChoć ta zapłata może ci się wydać nieco skromniejsza, niż $gprzywykłeś:przywykłaś;, możesz być $gpewien:pewna;, że twoje wielkie czyny na niwie goblinizmu odbijają się echem w salach władzy Kartelu Parochlebców. Jeśli potrzebujesz innego zajęcia, koniecznie ze mną porozmawiaj!', 0),
(7726, 'plPL', 'Pierwsza klasa, $N, pierwsza klasa! Choć zapłata, którą ci daję, może nie jest najwyższą, jaką kiedykolwiek dostaniesz za taką pracę, możesz być $gpewien:pewna;, że moi towarzysze z Kartelu Parochlebców usłyszą o twoich wysiłkach!$B$BJeśli szukasz innego zajęcia, daj znać. Zawsze przydadzą mi się kolejne rdzenie żywiołaków i tym podobne.', 0),
(7730, 'plPL', 'Dobra robota, $N. Choć tak rozległej obecności Zukk\'ash nie powstrzyma nic poza inwazją na pełną skalę, $gzyskałeś:zyskałaś; dla nas trochę czasu, byśmy mogli opracować właściwą strategię.$B$BDopilnuję, żeby te pancerze zbadano; musimy dowiedzieć się o nich wszystkiego, zanim zajmiemy się czymś, co niestety okazało się znacznie większym problemem, niż przewidywaliśmy.', 0),
(7731, 'plPL', 'Imponujące, $N... wielce imponujące! Jeśli Żądłobicz rzeczywiście jest jednym z ich najsilniejszych stworzeń, zbadanie tej bestii z czasem okaże się bardzo cenne. Teraz moim zadaniem jest dopilnować, żebyśmy bronili się dość długo, by móc to wykorzystać.$B$BPrzyjmij, proszę, tę nagrodę w monetach jako wyraz wdzięczności całego obozu, $N. Dobra robota.', 0),
(7733, 'plPL', 'Doskonale, doskonale! Sprawdzą się niesamowicie – już widzę, że po właściwej obróbce będą znacznie twardsze.$B$BJeszcze raz dzięki za pomoc, $N. Proszę – weź jeden z moich najnowszych wyrobów.', 0),
(7734, 'plPL', 'Doskonale, doskonale! Sprawdzą się niesamowicie – już widzę, że po właściwej obróbce będą znacznie twardsze.$B$BJeszcze raz dzięki za wsparcie, $N. Proszę – weź jeden z moich najnowszych wyrobów.', 0),
(7735, 'plPL', 'Niesamowite! Chyba $gznalazłeś:znalazłaś; matkę wszystkich skór yeti!$B$BMożesz być $gpewien:pewna;, że ci za nią zapłacę. Zwykle nie płacę tyle za jedną skórę, ale jestem prawie pewien, że zrobię z niej coś wyjątkowego. Dzięki, że o mnie $gpomyślałeś:pomyślałaś;, $N!', 0),
(7738, 'plPL', 'Niesamowite znalezisko! To chyba najwspanialszy okaz skóry yeti, jaki kiedykolwiek widziałem!$B$BZaiste, zasługuje na odpowiednią nagrodę. Zwykle nie płacę tyle za jedną skórę, ale jestem przekonany, że zrobię z niej coś wyjątkowego. Dzięki, że o mnie $gpomyślałeś:pomyślałaś;, $N!', 0),
(11746, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Feralas!', 0),
(11773, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Feralas!', 0),
(11817, 'plPL', 'Uczcij płomień Feralas!', 0),
(11849, 'plPL', 'Uczcij płomień Feralas!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(2523, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(2821, 'plPL', 'Za dziesięć grubych skór yeti możesz wybrać jeden z moich wyrobów. Dbam o jakość, więc mogę ci zagwarantować, że dostaniesz dobrą rzecz!$B$BJeśli nie możesz znaleźć yeti, wiem, gdzie mogą być. Poszukaj nieco w głąb lądu od Zapomnianego Wybrzeża, w okolicach Doliny Dzikiej Blizny.', 0),
(2822, 'plPL', 'Udało ci się zdobyć dziesięć grubych skór yeti? Moje skórzane wyroby nie mają sobie równych i podzielę się z tobą próbką, jeśli masz skóry.$b$bJeśli nie możesz znaleźć yeti, wiem, gdzie mogą być. Poszukaj na zachód stąd, nieco w głąb lądu od Zapomnianego Wybrzeża, w okolicach Doliny Dzikiej Blizny.', 0),
(2845, 'plPL', 'Już się o ciebie martwiłem! Wielkie dzięki, że $gprzyprowadziłeś:przyprowadziłaś; Shay do domu, $N.', 0),
(2847, 'plPL', 'Jak mówiłem, będziesz dla mnie pracować, póki uczysz się o dzikiej skórzanej zbroi. Dzikie pnącze jest zarówno potężne, jak i chaotyczne, więc nadaje losową, ale silną premię i tak już mocnej zbroi, którą będziesz wytwarzać. Tej wiedzy jednak nie zdobyłem łatwo.$B$BNa początek wystarczy dziesięć sztuk grubej skóry.$B$BGdy to załatwimy, zajmiemy się pracą, którą musisz wykonać, aby zdobyć wykroje.', 0),
(2848, 'plPL', 'Masz sześć grubych zestawów pancernych i dzikie pnącze, o które prosiłem?$B$BNie myśl o robieniu zestawów pancernych jak o monotonnej pracy. Równa, pewna metoda wykonania, którą wyrabiasz sobie, pracując nad tymi zestawami, rozwija umiejętności potrzebne do misternej roboty przy dzikiej skórzanej zbroi.$B$BWidzisz? To, co dla mnie robisz, ma swój prawdziwy cel...', 0),
(2849, 'plPL', 'Masz te dwa napierśniki i rękawice z żółwich łusek, które zamówiłem? I nie zapomnij o dzikim pnączu!$B$BJuż przy najwcześniejszych wykrojach uczymy się, że podstawy kształtu dobrze przekładają się na trudniejsze wyroby. Choć to inne przedmioty, kształt napierśnika z żółwich łusek przygotowuje cię do szczegółów potrzebnych przy dzikiej skórzanej kamizelce.$B$BA rękawice... cóż, te są dla mnie. Pamiętaj, pracujesz dla mnie!', 0),
(2850, 'plPL', 'Potrzebuję tych tunik i opasek, a do tego kawałka dzikiego pnącza, zanim podzielę się z tobą wiedzą o dzikich skórzanych hełmach.$B$BNakrycia głowy są wśród poszukiwaczy przygód bardzo pożądane, czy to rozbrajająco prosta opaska, czy hełm zakrywający całą głowę. Podstawy tworzenia cenionych nakryć głowy pozostają takie same, bez względu na to, jak wyglądają.', 0),
(2851, 'plPL', 'Zanim dostaniesz wykrój, musisz zrealizować zamówienie na spodnie, buty i dzikie pnącza, $N. $GSkończyłeś:Skończyłaś;?$B$BJuż przy pierwszej parze butów, jaką uczymy się robić, zaczynamy rozumieć, że dobry but musi balansować na ostrzu brzytwy między wygodą a użytecznością. Łącząc jedno z drugim, tworzymy przedmioty, dzięki którym noszący nie czuje zmęczenia, które powaliłoby tych, co noszą gorsze wyroby.', 0),
(2852, 'plPL', 'Masz już gotowe karwasze i hełmy z żółwich łusek? Nie zapomnij o dwóch dzikich pnączach, których potrzebuję!$B$BTeraz już zaczynasz dostrzegać potencjalną moc, jaka tkwi w dzikiej skórzanej zbroi. Zbroja o nieograniczonych zastosowaniach jest dla garbarza niemal bezcenna. Ograniczeniem jest tylko ilość surowców potrzebnych do wykonania przedmiotów – a nie jakość gotowych wyrobów!', 0),
(2854, 'plPL', 'Postawmy sprawę jasno: póki uczysz się sztuki dzikiej skórzanej zbroi, będziesz $gmoim uczniem:moją uczennicą;. Dzikie pnącze jest zarówno potężne, jak i chaotyczne, więc nadaje losową, ale silną premię i tak już mocnej zbroi, którą będziesz wytwarzać. Tej wiedzy jednak nie zdobyłem łatwo.$b$bNa początek wystarczy dziesięć sztuk grubej skóry.$b$bGdy to załatwimy, zajmiemy się pracą, którą musisz wykonać, aby zdobyć wykroje.', 0),
(2855, 'plPL', 'Masz sześć grubych zestawów pancernych i dzikie pnącze, o które prosiłem?$b$bTraktuj robienie zestawów pancernych jak lekcję równego i rzetelnego rzemiosła. Stała metoda wykonania, którą wyrabiasz sobie, pracując nad tymi zestawami, rozwija umiejętności potrzebne do misternej roboty przy dzikich skórzanych zbrojach.$b$bKażda lekcja ma swój cel, $N. Ważne, by każdą przyjąć tak, jak należy.', 0),
(2856, 'plPL', 'Masz te dwa napierśniki i rękawice z żółwich łusek? I nie zapomnij o dzikim pnączu!$b$bJuż przy najwcześniejszych wykrojach uczymy się, że podstawy kształtu dobrze przekładają się na trudniejsze wyroby. Choć to inne przedmioty, kształt napierśnika z żółwich łusek przygotowuje cię do szczegółów potrzebnych przy dzikiej skórzanej kamizelce.$b$bW miarę postępów w nauce umiejętności, których cię uczę, staną się sztuką.', 0),
(2857, 'plPL', 'Potrzebuję tych tunik i opasek, a do tego kawałka dzikiego pnącza, zanim podzielę się z tobą wiedzą o dzikich skórzanych hełmach.$b$bNakrycia głowy są wśród poszukiwaczy przygód bardzo pożądane, czy to rozbrajająco prosta opaska, czy hełm zakrywający całą głowę. Podstawy tworzenia cenionych nakryć głowy pozostają takie same, bez względu na to, jak wyglądają.', 0),
(2858, 'plPL', 'Zanim poznasz wykrój, musisz mi dostarczyć spodnie, buty i dzikie pnącza, $N. $GZrobiłeś:Zrobiłaś;, o co prosiłem?$b$bJuż przy pierwszej parze butów, jaką uczymy się robić, zaczynamy rozumieć, że dobry but musi balansować na ostrzu brzytwy między wygodą a użytecznością. Łącząc jedno z drugim, tworzymy przedmioty, dzięki którym noszący nie czuje zmęczenia, które powaliłoby tych, co noszą gorsze wyroby.', 0),
(2859, 'plPL', 'Masz już gotowe karwasze i hełmy z żółwich łusek? Nie zapomnij o dwóch dzikich pnączach, których potrzebuję.$b$bTeraz już zaczynasz dostrzegać potencjalną moc, jaka tkwi w dzikiej skórzanej zbroi. Zbroja o nieograniczonych zastosowaniach jest dla garbarza niemal bezcenna. Ograniczeniem jest tylko ilość surowców potrzebnych do wykonania przedmiotów – a nie jakość gotowych wyrobów!', 0),
(2862, 'plPL', 'Odpieramy je, a one wciąż atakują! Ktoś albo coś musi doprowadzać je do szału... O, $gwróciłeś:wróciłaś;, $N? Masz grzywy, których potrzebuję, by wypłacić nagrodę?', 0),
(2863, 'plPL', 'Czas ucieka, $N! Jeśli nie przychodzisz zameldować, że $gzałatwiłeś:załatwiłaś; samców alfa, to marnujesz czas!', 0),
(2869, 'plPL', '$N, jeśli przychodzisz w sprawie powierzonego ci zadania, to świetnie – szukam dziesięciu łusek Nienawistnego Grzebienia. Jeśli $gprzyszedłeś:przyszłaś; na pogawędkę, to obecnie nie mam czasu na takie błahostki.$B$BWiedz jedno: my, nocne elfy, nie jesteśmy podżegaczami wojennymi. Nasza rasa poświęca się zachowaniu pokoju i harmonii. Nie znaczy to jednak, że nie będziemy aktywnie chronić własnych interesów. To mój obowiązek wobec generał Lunopiórej i wobec warowni.', 0),
(2870, 'plPL', 'Zabicie lorda Shalzaru z pewnością opóźni ich plany o tygodnie, jeśli nie miesiące. Co więcej, odkryta przez niego relikwia bardzo nas interesuje.$B$B$GWykonałeś:Wykonałaś; powierzoną ci misję, $N?', 0),
(2871, 'plPL', 'Tak, w czym mogę pomóc?$B$BChwileczkę, czy to nie ty $gpomagałeś:pomagałaś; generał Lunopiórej i Latro w sprawie zagrożenia ze strony nag? Jestem Vestia, żona Latro... ekhm, raczej Latronicusa. Miło cię poznać!$B$BWybacz, oczywiście przychodzisz w interesach. Masz coś dla mnie – może od niego?', 0),
(2878, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(2879, 'plPL', 'Monolit Equinex stoi w milczeniu pośród ruin. Co może skrywać?', 0),
(2903, 'plPL', 'Witaj z powrotem, $N. Udało ci się znaleźć jakieś namacalne dowody na plany gnoli?', 0),
(2942, 'plPL', 'Cieszę się, że $gwróciłeś:wróciłaś;, $N. Nie mogę się doczekać, by usłyszeć o twoich odkryciach.', 0),
(2970, 'plPL', 'Kindal potrzebuje czasu na przygotowania, ale nasze ofiary liczymy już w dziesiątkach. Klan Ponurego Totemu doskonale wie o naszej obecności w okolicy i tropi nas niczym żmije.$B$BZrobią wszystko, co w ich mocy, żeby pozbawić nas głów. Miej się na baczności... teraz, gdy się $gwtrąciłeś:wtrąciłaś;, przyjdą także po ciebie.', 0),
(2973, 'plPL', 'Sprowokowane duszkowce potrafią być groźnymi stworzonkami. Uważaj na nie, $N. A jeszcze bardziej uważaj na nocne elfy w okolicy. Te natrętne głupki też lubią się zaszywać w lasach.$b$bGdy zbierzesz dość skrzydeł, daj mi znać – na pewno sowicie cię wynagrodzę!', 0),
(2974, 'plPL', 'Potraktuj moje słowa poważnie, $N: klan Ponurego Totemu jest zły. Skoro $godkryłeś:odkryłaś;, gdzie przebywają, to do ciebie należy powrót i zadanie ich klanowi pierwszego ciosu... zanim wkroczą na nasze ziemie, spalą nasze wioski i złupią nasze tereny.', 0),
(2975, 'plPL', 'Pośpiesz się, $N. A może zadanie, o które prosiłam, jest dla ciebie zbyt trudne?', 0),
(2978, 'plPL', 'Co to jest?', 0),
(2979, 'plPL', 'Musimy się dowiedzieć, dlaczego Gordunni tu przybyli, $N.', 0),
(2980, 'plPL', '$GZnalazłeś:Znalazłaś; ruiny, $N?', 0),
(2982, 'plPL', 'Uważaj na Gordunni, $N. Ich magia zdaje się pustoszyć samą ziemię, po której stąpają.', 0),
(2987, 'plPL', 'Ruszaj tam i zacznij kopać!$b$bMam miejsca do odwiedzenia i ludzi do zobaczenia – czas to pieniądz!', 0),
(3062, 'plPL', 'Nienawiść, którą Edana szerzy w tej krainie, musi zostać powstrzymana.', 0),
(3063, 'plPL', 'Skrzydła harpii Północnego Źródła są czarne jak noc. Nie spuszczaj ich z oczu, bo rozpłyną się w ciemności.', 0),
(3122, 'plPL', '$GRozmawiałeś:Rozmawiałaś; z Neeru?', 0),
(3123, 'plPL', '$GZdołałeś:Zdołałaś; schwytać dziczołaki?$b$bJeśli ci się uda, będziemy gotowi pomniejszać stworzenia Feralas i chwytać ich muisek.', 0),
(3124, 'plPL', '$GZdołałeś:Zdołałaś; schwytać hipogryfy?', 0),
(3125, 'plPL', '$GZdołałeś:Zdołałaś; schwytać muisek baśniowych smoków?', 0),
(3126, 'plPL', '$GZdołałeś:Zdołałaś; schwytać błądzących leśnych wędrowców?', 0),
(3127, 'plPL', '$GZdołałeś:Zdołałaś; schwytać górskie olbrzymy?', 0),
(3128, 'plPL', '$GZdołałeś:Zdołałaś; zebrać potrzebne mi materiały?', 0),
(3363, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(3791, 'plPL', 'Szukam dziesięciu sztuk jutroziarna – tyle powinno wystarczyć, żeby przynajmniej rozpocząć badania. Na pewno sporo zmarnuję, idąc fałszywymi tropami, ale taka już natura badań.', 0),
(3792, 'plPL', 'Witaj ponownie, $N. Moje badania postępują całkiem nieźle, ale jeśli masz jeszcze pięć sztuk jutroziarna, chętnie cię od nich uwolnię. No cóż... „chętnie” to w tym przypadku przenośnia; im dłużej przebywam w ich pobliżu, tym bardziej czuję się nieswojo. Mimo to moje badania wymagają, żebym zacisnął zęby i przez to przebrnął.', 0),
(4041, 'plPL', 'Przynieś mi ewokorzeń, a pewnie, zrobię ci ten Eliksir Videre.$B$BZnam się na ziołach i alchemii jak mało kto... Ot, pozwól, że opowiem ci, jak transmutowałem złoto z sera, który miałem zjeść na obiad... hej... Dokąd idziesz?', 0),
(4114, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(4116, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(4118, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(4120, 'plPL', 'Wszystko, czego dotknęło spaczenie, emanuje dziwną zieloną poświatą... Wyczuwam w tym zło, ale zarazem ogromną moc.', 0),
(4127, 'plPL', 'Ach, witaj z powrotem, $N. Mam nadzieję, że $gzdołałeś:zdołałaś; odkryć jakąś wskazówkę co do ostatecznego losu Raschala, choćby był najtragiczniejszy.', 0),
(4129, 'plPL', 'Ginro cię przysłał, co?$B$BMoje psychometryczne odczyty mocno wyczerpują umysł... ale moje przegrane w Kalimdor Hold\'em też. Tu, w warowni, nazywają mnie „Królem pechowych rozdań”. Pech w kartach... szczęście w zgłębianiu tajemnic natury, jak sądzę.$B$BTak czy inaczej, oczywiście to zrobię. To może być właśnie przełom, którego potrzebujemy, by poznać los Raschala. Jeśli podasz mi nóż, możemy zaczynać.', 0),
(4142, 'plPL', 'Mieszkam tu, w lesie... W spokoju.$B$BNo, przynajmniej tak myślałem. Mam tu więcej gości niż kiedykolwiek, gdy mieszkałem w Żelaznej Kuźni!', 0),
(4143, 'plPL', 'Larion wciąż się do mnie nie odzywa! Ten to potrafi chować urazę.', 0),
(4265, 'plPL', 'Masz coś do zameldowania, $n?', 0),
(4281, 'plPL', 'Witaj w Thalanaar. Potrzebujesz jakiejś pomocy?', 0),
(4401, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(4464, 'plPL', '$GZnalazłeś:Znalazłaś; chorowitą, skażoną odmianę czegoś, co wygląda na śpiewokwiat. Od rośliny bije ostry, niezdrowy zapach. Rozpaczliwie potrzebuje jakiejś opieki, jeśli ma wrócić do normalnego stanu.', 0),
(7003, 'plPL', 'Pozostałość po miniaturyzacji, zapewniam cię, to cenny towar, jeśli chodzi o inżynierię! No, cenny w tym sensie, że pomaga mi się upewnić, że porażacz nie zrobi czegoś tak rozczarowującego jak wybuch w rękach użytkownika.$B$BTo znaczy, chodzi mi o porażacze inne niż ten, który ci dałem. Absolutnie!', 0),
(7441, 'plPL', 'Niczego nie żałuję, $gnieznajomy:nieznajoma;. Królowej dawno już nie ma. Dzieło Shen\'Dralar zostało skalane szaleństwem księcia Tortheldrina. Szukam tylko wolności... Ucieczki...', 0),
(7481, 'plPL', 'Moja wspólniczka, uczona Runiczny Cierń z rasy nocnych elfów, zbiera sojuszników do tego zadania.', 0),
(7482, 'plPL', 'Moja wspólniczka, uczona Runiczny Cierń z rasy nocnych elfów, zbiera sojuszników do tego zadania.', 0),
(7488, 'plPL', 'Masz sieć, $N? Zgromadzona w niej magiczna energia musi zostać rozproszona!', 0),
(7489, 'plPL', '$N, masz sieć Lethtendris?', 0),
(7721, 'plPL', 'Mógłbym cię zanudzać technicznymi szczegółami przydatności rdzeni żywiołaków, ale zamiast tego skuszę cię do ukończenia tego ważnego zadania, oferując w zamian cenne monety i nagrody. Rzeknij tedy, zaprawdę, czy już $gskończyłeś:skończyłaś;?', 0),
(7725, 'plPL', 'Ach, owoce badań i zastosowań w postaci słodziutkiej, słodziutkiej pozostałości. No, to znaczy, nie próbuję jej ani nic w tym stylu, kiedy ją badam.$B$BZa często.', 0),
(7726, 'plPL', '$GZdołałeś:Zdołałaś; znaleźć rdzenie żywiołaków, których potrzebuję?', 0),
(7730, 'plPL', 'Jak idą łowy, $N? Przychodzisz zameldować o sukcesie?', 0),
(7731, 'plPL', 'Udało ci się już pokonać Żądłobicza?', 0),
(7733, 'plPL', 'Jeśli te skóry yeti Szramy Wściekłości choć trochę dorównują jakością skórom ich krewniaków z Dzikiej Blizny, mogą być wytrzymałe jak torium!$B$BWyobraź to sobie!', 0),
(7734, 'plPL', 'Jeśli te skóry yeti Szramy Wściekłości choć trochę dorównują jakością skórom ich krewniaków z Dzikiej Blizny, mogą być wytrzymałe jak torium!$B$BWyobraź to sobie!', 0),
(7735, 'plPL', 'Co to, $N – masz dla mnie coś wyjątkowego?', 0),
(7738, 'plPL', 'Co to, $N – masz dla mnie coś wyjątkowego?', 0),
(8520, 'plPL', 'Potrzebuję tych tunik i opasek, a do tego kawałka dzikiego pnącza, zanim podzielę się z tobą wiedzą o dzikich skórzanych hełmach.$B$BNakrycia głowy są wśród poszukiwaczy przygód bardzo pożądane, czy to rozbrajająco prosta opaska, czy hełm zakrywający całą głowę. Podstawy tworzenia cenionych nakryć głowy pozostają takie same, bez względu na to, jak wyglądają.', 0),
(10756, 'plPL', 'Co to jest?', 0),
(10762, 'plPL', 'Co to jest?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(7900, 0, 'plPL', 'Witaj, $N. Może masz chwilę na pogawędkę?', 0);
