(7114, 'plPL', 'Może to jednak nie było najlepsze miejsce na sklep...', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3713, 'plPL', '%s w ostatnim desperackim odruchu szykuje się do użądlenia ofiary!', '', 0),
(3906, 'plPL', '', 'Och, tu jesteś!', 0),
(3907, 'plPL', '', 'Och, jaki piękny kwiat tam rośnie...', 0),
(3908, 'plPL', '', 'Te drzewa są wspaniałe, prawda?', 0),
(3909, 'plPL', '', 'Na pewno idziemy dobrą drogą? Może powinniśmy pójść raczej tędy...', 0),
(3911, 'plPL', '', 'Hmmm, ciekawe, co tam jest?', 0),
(3912, 'plPL', '', 'Wybraliśmy trasę widokową?', 0),
(3913, 'plPL', '', 'Och, znowu się oddaliłam. Przepraszam.', 0),
(3914, 'plPL', '', 'Ale przygoda!', 0),
(3915, 'plPL', '', 'Naprawdę nic na to nie poradzę. To po prostu takie piękne miejsce.', 0),
(3916, 'plPL', '', 'Znowu ten dzwonek, co za słodki dźwięk.', 0),
(3917, 'plPL', '', 'Och, tu jesteś, Skałogryzie! Przepraszam, wiem, że nie powinnam się oddalać.', 0),
(3918, 'plPL', '', '%s zaczyna się oddalać.', 0),
(3921, 'plPL', '', 'Nie zapomnij wyjąć mojego dzwonka z tej skrzyni. I pamiętaj: jeśli się oddalę, po prostu w niego zadzwoń, a znów cię odnajdę.', 0),
(3922, 'plPL', 'Tak się cieszę, żeś wróciła, Shay. Proszę, nie uciekaj mi już nigdy w ten sposób! Co bym powiedział twoim rodzicom, gdybym cię zgubił?', '', 0),
(4175, 'plPL', '%s zbiera materiały i zabiera się do pracy.', '', 0),
(4176, 'plPL', 'Broń jest gotowa, $n.', '', 0),
(4179, 'plPL', 'Niesamowitą moc można znaleźć w duchach, czyli „muisek”, stworzeń, z którymi walczymy.$B$BZajrzyj w głąb siebie; naucz się okiełznać moc własnego ducha, a staniesz się $gpotężniejszy:potężniejsza;, niż kiedykolwiek $gsobie wyobrażałeś:sobie wyobrażałaś;.', '', 0),
(4180, 'plPL', 'Naczynia na muisek są gotowe, $n.', '', 0),
(4181, 'plPL', '%s rozpoczyna rytuał.', '', 0),
(4419, 'plPL', 'Opowiedz mi więcej o muisek.', 'Opowiedz mi więcej o muisek.', 0),
(4420, 'plPL', 'W tej okolicy żyje wiele stworzeń uważanych za sojuszników nocnych elfów. Elfy miały dostęp do mocy każdego z nich; czas, by Horda mogła się nią nacieszyć tak samo. Wymyśliłem sposób, by tę moc schwytać i wykorzystać dla naszych korzyści.$B$BNie wątp w moje słowa, $n. Pomóż mi, a przekonasz się, że mówię prawdę.', '', 0),
(4511, 'plPL', 'Wiem, wiem, siedzę tu na końcu świata!$B$BTak naprawdę mieszkam w Zapadce, ale gdy rozbiłem tu swój sterowiec, pomyślałem, że równie dobrze mogę zacząć badania, dla których tu przybyłem!', '', 0),
(4517, 'plPL', '', 'Kraina Feralas wiele przeszła. Ziemia, drzewa, stworzenia – wszystko to zmienia, czym Feralas jest i czym będzie.$B$BBliźniacze Kolosy nad nami trwają jednak niezmiennie mimo wszystkiego, co się tu wydarzyło...', 0),
(4518, 'plPL', 'Tym, którzy chcą bezpiecznie zejść na dół, użyczam skrzydeł.', '', 0),
(4519, 'plPL', 'Pomożesz mi zejść na dół?', 'Pomożesz mi zejść na dół?', 0),
(4720, 'plPL', 'Kupisz coś, co?', 'Kupisz coś, co?', 0),
(4721, 'plPL', 'Jak mogę zdobyć Eliksir Videre?', 'Jak mogę zdobyć Eliksir Videre?', 0),
(4722, 'plPL', 'Jasne, $n. Wyglądasz na kogoś, komu można zaufać... Wiarygodność! Wyczuwam ją na milę...$B$BW każdym razie, wracając do tego, co mówiłem. Do zrobienia Eliksiru Videre potrzeba jednej rośliny ewokorzenia. Reszta składników to w sumie drobiazgi, ale ewokorzeń... cóż, z nim może być trochę kłopotu.', '', 0),
(4760, 'plPL', 'Burk, burk...', '', 0),
(4766, 'plPL', 'Burk...', '', 0),
(4768, 'plPL', '%s obwąchuje przynętę.', '', 0),
(4771, 'plPL', '%s łapczywie obgryza przynętę.', '', 0),
(4827, 'plPL', 'Jak mogę zdobyć ewokorzeń?', 'Jak mogę zdobyć ewokorzeń?', 0),
(4828, 'plPL', 'He, he... Ale z ciebie ciekawska dusza, co, $n? No dobra, oto co musisz zrobić.$B$BNa północ stąd, w starych ruinach, mieszka bardzo nieprzyjemny gnol imieniem Miblon Warkozęby. Pilnuje jedynego ewokorzenia, o jakim wiem, i strzeże go dniem i nocą! Chyba nawet nigdy nie śpi!$B$BMożesz go przekupić. Mogę ci sprzedać trochę przynęty, która mu zasmakuje – po prostu połóż ją obok niego, a to odwróci jego uwagę na tyle długo, żebyś $gzdążył:zdążyła; chwycić ewokorzeń. Powodzenia!', '', 0),
(4836, 'plPL', '%s porzuca stanowisko, z którego blokował przejście, i spogląda w stronę przynęty.', '', 0),
(4966, 'plPL', 'Mam nadzieję, że to zadziała!', '', 0),
(4967, 'plPL', '%s dodaje mgiełkę do kiełków krwawopłatka.', '', 0),
(4968, 'plPL', 'Patrz, jak zmykają!', '', 0),
(4969, 'plPL', '%s śmieje się, patrząc, jak szkodniki uciekają.', '', 0),
(5254, 'plPL', 'Wielkie sanktuarium zbudowały przed wieloma laty nocne elfy, które niegdyś zamieszkiwały tę krainę.$B$BJakie sekrety może skrywać?', '', 0),
(6294, 'plPL', '', 'Las powiedział mi o twojej obecności, ale nie o tym, po co tu jesteś. Mów więc i oświeć mnie.', 0),
(7769, 'plPL', '', 'Niegdyś witałam ciemność z radością, bo była siostrą nocy. Teraz ciemno jest cały czas, nawet za dnia, a lasy wołają o pokarm. Jeśli wkrótce nie zadziałamy, ta szerząca się zaraza pokryje cały świat.', 0),
(7907, 'plPL', '', 'Jeśli szukasz naprawdę satysfakcjonującego zajęcia, zaklinanie jest dla ciebie!', 0),
(8055, 'plPL', '', 'Wszystkie zamówienia na moją pracę kupujący musi składać osobiście. Orwin często prosi mnie, żebym to przemyślała, ale moje priorytety są tutaj. Rozejrzyj się: wielu z tych wojowników polega na mnie, jeśli chodzi o pancerze.', 0),
(9443, 'plPL', '', 'Och, cóż za zgroza! Cóż za tragedia! Jesteśmy o krok od przełomu, a wszystko może przepaść.', 0),
(9817, 'plPL', 'Masz coś ciekawego na sprzedaż, Zorbinie?', 'Masz coś ciekawego na sprzedaż, Zorbinie?', 0),
(9820, 'plPL', 'No witaj ponownie, $n! Nie wiem, jak długo jeszcze będę próbował rozkręcić sklep na końcu świata. Ale skoro już mi kiedyś $gpomogłeś:pomogłaś;, pokażę ci kilka rzeczy, które mogą cię zainteresować!', '', 0),
(10884, 'plPL', 'Zakosztujcie zepsucia własnego świata!', '', 0),
(10885, 'plPL', 'Nadzieja to CHOROBA duszy! Ta kraina uschnie i sczeźnie!', '', 0),
(11596, 'plPL', 'Gdzie jest Nestor Rozłupana Skała?', 'Gdzie jest Nestor Rozłupana Skała?', 0),
(11597, 'plPL', 'Nestor Rozłupana Skała jest chyba teraz w Maraudonie w Mrocznym Pustkowiu.', 'Nestor Rozłupana Skała jest chyba teraz w Maraudonie w Mrocznym Pustkowiu.', 0),
(43512, 'plPL', 'Ja źle się czuć.', '', 0);
